export default "###\\n    # NEW\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.ptr_current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple(model, idx, max_new_tokens, context_size):\\n    # idx is (B, T) array of indices in the current context\\n    for _ in range(max_new_tokens):\\n\\n        # Crop current context if it exceeds the supported context size\\n        # E.g., if LLM supports only 5 tokens, and the context size is 10\\n        # then only the last 5 tokens are used as context\\n        idx_cond = idx[:, -context_size:]\\n\\n        # Get the predictions\\n        with torch.no_grad():\\n            logits = model(idx_cond)\\n\\n        # Focus only on the last time step\\n        # (batch, n_token, vocab_size) becomes (batch, vocab_size)\\n        logits = logits[:, -1, :]\\n\\n        # Get the idx of the vocab entry with the highest logits value\\n        idx_next = torch.argmax(logits, dim=-1, keepdim=True)  # (batch, 1)\\n\\n        # Append sampled index to the running sequence\\n        idx = torch.cat((idx, idx_next), dim=1)  # (batch, n_tokens+1)\\n\\n    return idx\\n\\n\\n####################################################\\n# NEW\\ndef generate_text_simple_cached(model, idx, max_new_tokens, context_size=None, use_cache=True):\\n    model.eval()\\n\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n    kv_window_size = model.kv_window_size\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            model.reset_kv_cache()\\n\\n            input_tokens = idx[:, -ctx_len:]\\n            input_tokens_length = input_tokens.size(1)\\n\\n            # prefill to handle input_tokens_length > kv_window_size\\n            for i in range(0, input_tokens_length, kv_window_size):\\n                chunk = input_tokens[:, i:i+kv_window_size]\\n                logits = model(chunk, use_cache=True)\\n\\n            # can't generate more than ctx_len of result\\n            # due to the limitation of position embedding\\n            max_generable = ctx_len - input_tokens_length\\n            max_new_tokens = min(max_new_tokens, max_generable)\\n\\n            for _ in range(max_new_tokens):\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n####################################################\\n\\n\\ndef main():\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,     # Vocabulary size\\n        \\\"context_length\\\": 1024,  # Context length\\n        \\\"emb_dim\\\": 768,          # Embedding dimension\\n        \\\"n_heads\\\": 12,           # Number of attention heads\\n        \\\"n_layers\\\": 12,          # Number of layers\\n        \\\"drop_rate\\\": 0.1,        # Dropout rate\\n        \\\"qkv_bias\\\": False,       # Query-Key-Value bias\\n        \\\"kv_window_size\\\": 1024   # NEW: KV cache window size\\n    }\\n\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device)\\n    model.eval()  # disable dropout\\n\\n    start_context = \\\"Hello, I am\\\"\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    # token_ids = generate_text_simple(\\n    #     model=model,\\n    #     idx=encoded_tensor,\\n    #     max_new_tokens=200,\\n    #     context_size=GPT_CONFIG_124M[\\\"context_length\\\"]\\n    # )\\n\\n    ####################################################\\n    # NEW\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=200,\\n    )\\n    ####################################################\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/03_kv-cache/tests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e74747dc7f7048f2664f93207c883b0f048a16a9171fb519a8ebf7126b6f6ded\",\"content\":\"# Code to test the GPT model implementation against the KV cache variants\\n\\nimport pytest\\nimport torch\\nimport tiktoken\\n\\nfrom gpt_ch04 import GPTModel as GPTModelBase\\nfrom gpt_ch04 import generate_text_simple\\n\\nfrom gpt_with_kv_cache import GPTModel as GPTModelKV1\\nfrom gpt_with_kv_cache_optimized import GPTModel as GPTModelKV2\\nfrom gpt_with_kv_cache import generate_text_simple_cached as generate_text_simple_cachedKV1\\nfrom gpt_with_kv_cache_optimized import generate_text_simple_cached as generate_text_simple_cachedKV2\\n\\n\\nGPT_CONFIG_124M = {\\n    \\\"vocab_size\\\": 50257,\\n    \\\"context_length\\\": 1024,\\n    \\\"emb_dim\\\": 768,\\n    \\\"n_heads\\\": 12,\\n    \\\"n_layers\\\": 12,\\n    \\\"drop_rate\\\": 0.1,\\n    \\\"qkv_bias\\\": False,\\n    \\\"kv_window_size\\\": 1024  # NEW: KV cache window size\\n}\\n\\n\\ndevice = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"ModelClass\\\", [GPTModelBase, GPTModelKV1, GPTModelKV2])\\ndef test_gpt_model_equivalence_not_cached(ModelClass):\\n    torch.manual_seed(123)\\n\\n    model = ModelClass(GPT_CONFIG_124M).to(device)\\n    model.eval()\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    prompt = \\\"Hello, I am\\\"\\n    encoded = tokenizer.encode(prompt)\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n\\n    model_name = ModelClass.__module__ + \\\".\\\" + ModelClass.__name__\\n\\n    token_ids = generate_text_simple(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=30,\\n        context_size=GPT_CONFIG_124M[\\\"context_length\\\"]\\n    )\\n\\n    if not hasattr(test_gpt_model_equivalence_not_cached, \\\"results\\\"):\\n        test_gpt_model_equivalence_not_cached.results = []\\n\\n    test_gpt_model_equivalence_not_cached.results.append((model_name, token_ids))\\n\\n    if len(test_gpt_model_equivalence_not_cached.results) == 3:\\n        base_name, base_output = test_gpt_model_equivalence_not_cached.results[0]\\n        for other_name, other_output in test_gpt_model_equivalence_not_cached.results[1:]:\\n            assert torch.equal(base_output, other_output), (\\n                f\\\"Mismatch between {base_name} and {other_name}\\\"\\n            )\\n\\n\\n@pytest.mark.parametrize(\\\"ModelClass\\\", [GPTModelBase, GPTModelKV1, GPTModelKV2])\\ndef test_gpt_model_equivalence_cached(ModelClass):\\n    torch.manual_seed(123)\\n\\n    model = ModelClass(GPT_CONFIG_124M).to(device)\\n    model.eval()\\n\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    prompt = \\\"Hello, I am\\\"\\n    encoded_tensor = torch.tensor(tokenizer.encode(prompt), device=device).unsqueeze(0)\\n\\n    model_name = ModelClass.__module__ + \\\".\\\" + ModelClass.__name__\\n\\n    if ModelClass is GPTModelBase:\\n        token_ids = generate_text_simple(\\n            model=model,\\n            idx=encoded_tensor,\\n            max_new_tokens=30,\\n            context_size=GPT_CONFIG_124M[\\\"context_length\\\"]\\n        )\\n    elif ModelClass is GPTModelKV1:\\n        token_ids = generate_text_simple_cachedKV1(\\n            model=model,\\n            idx=encoded_tensor,\\n            max_new_tokens=30,\\n            context_size=GPT_CONFIG_124M[\\\"context_length\\\"]\\n        )\\n    else:\\n        token_ids = generate_text_simple_cachedKV2(\\n            model=model,\\n            idx=encoded_tensor,\\n            max_new_tokens=30,\\n            context_size=GPT_CONFIG_124M[\\\"context_length\\\"]\\n        )\\n\\n    if not hasattr(test_gpt_model_equivalence_cached, \\\"results\\\"):\\n        test_gpt_model_equivalence_cached.results = []\\n\\n    test_gpt_model_equivalence_cached.results.append((model_name, token_ids))\\n\\n    if len(test_gpt_model_equivalence_cached.results) == 3:\\n        base_name, base_output = test_gpt_model_equivalence_cached.results[0]\\n        for other_name, other_output in test_gpt_model_equivalence_cached.results[1:]:\\n            assert torch.equal(base_output, other_output), (\\n                f\\\"Mismatch between {base_name} and {other_name}\\\"\\n            )\\n\\n\\ndef test_context_overflow_bug():\\n    \\\"\\\"\\\"\\n    Test that demonstrates the ptr_current_pos overflow bug.\\n\\n    In old implementation:\\n    - context_length = 10 (positions 0-9 available)\\n    - We try to generate 15 tokens total (5 input + 10 generated)\\n    - At token 11 (position 10), it crashes trying to access pos_emb[10]\\n    \\\"\\\"\\\"\\n    GPT_CONFIG_SMALL = {\\n        \\\"vocab_size\\\": 50257,\\n        \\\"context_length\\\": 10,  # Very small context\\n        \\\"emb_dim\\\": 768,\\n        \\\"n_heads\\\": 12,\\n        \\\"n_layers\\\": 12,\\n        \\\"drop_rate\\\": 0.1,\\n        \\\"qkv_bias\\\": False,\\n        \\\"kv_window_size\\\": 20  # Larger than context_length\\n    }\\n\\n    torch.manual_seed(123)\\n\\n    model = GPTModelKV2(GPT_CONFIG_SMALL).to(device)\\n    model.eval()\\n\\n    # 5 input tokens\\n    input_tokens = torch.randint(0, 50257, (1, 5), device=device)\\n\\n    generate_text_simple_cachedKV2(\\n        model=model,\\n        idx=input_tokens,\\n        max_new_tokens=10,  # 5 + 10 = 15 > 10 context_length\\n        context_size=GPT_CONFIG_SMALL[\\\"context_length\\\"],\\n        use_cache=True\\n    )\\n\\n\\ndef test_prefill_chunking_basic():\\n    \\\"\\\"\\\"\\n    Test that prefill correctly chunks input when input_length > kv_window_size.\\n\\n    Setup:\\n    - kv_window_size = 4\\n    - input_length = 10\\n    - Should process in 3 chunks: [0:4], [4:8], [8:10]\\n    \\\"\\\"\\\"\\n    config = {\\n        \\\"vocab_size\\\": 50257,\\n        \\\"context_length\\\": 20,\\n        \\\"emb_dim\\\": 768,\\n        \\\"n_heads\\\": 12,\\n        \\\"n_layers\\\": 12,\\n        \\\"drop_rate\\\": 0.1,\\n        \\\"qkv_bias\\\": False,\\n        \\\"kv_window_size\\\": 4  # Small window to force chunking\\n    }\\n\\n    torch.manual_seed(123)\\n    model = GPTModelKV2(config).to(device)\\n    model.eval()\\n\\n    # 10 input tokens (> kv_window_size of 4)\\n    input_tokens = torch.randint(0, 50257, (1, 10), device=device)\\n\\n    # Should successfully process all input in chunks\\n    token_ids = generate_text_simple_cachedKV2(\\n        model=model,\\n        idx=input_tokens,\\n        max_new_tokens=2,\\n        use_cache=True\\n    )\\n\\n    # Should have 10 input + 2 generated = 12 total\\n    assert token_ids.shape[1] == 12, f\\\"Expected 12 tokens, got {token_ids.shape[1]}\\\"\\n\\n    # First 10 tokens should match input\\n    assert torch.equal(token_ids[:, :10], input_tokens), \\\"Input tokens should be preserved\\\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/04_gqa/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"87425195f5b6d8dc8f76214168a153a12e07526e739183b544ad1c7b81377f02\",\"content\":\"# Grouped-Query Attention (GQA)\\n\\nThis bonus material illustrates the memory savings when using Grouped-Query Attention (GQA) over regular Multi-Head Attention (MHA).\\n\\n&nbsp;\\n## Introduction\\n\\nGrouped-Query Attention (GQA) has become the new standard replacement for a more compute- and parameter-efficient alternative to Multi-Head Attention (MHA) in recent years. Note that it's not new and goes back to the 2023 [GQA: Training Generalized Multi-Query Transformer Models from Multi-Head Checkpoints](https://arxiv.org/abs/2305.13245). And even the larger variants in the good old Llama 2 series used it.\\n\\nHere's a brief GQA summary. Unlike MHA, where each head also has its own set of keys and values, to reduce memory usage, GQA groups multiple heads to share the same key and value projections.\\n\\nFor example, as further illustrated in the figure below, if there are 3 key-value groups and 6 attention heads, then heads 1 and 2 share one set of keys and values, while heads 3 and 4, as well as heads 5 and 6, share another, respectively.\\n\\n&nbsp;\\n\\n![GQA](https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gqa-memory/1.webp?1)\\n\\n&nbsp;\\n\\nThis sharing of keys and values reduces the total number of key and value computations, which leads to lower memory usage and improved efficiency.\\n\\nSo, to summarize, the core idea behind GQA is to reduce the number of key and value heads by sharing them across multiple query heads. This (1) lowers the model's parameter count and (2) reduces the memory bandwidth usage for key and value tensors during inference since fewer keys and values need to be stored and retrieved from the KV cache.\\n\\nWhile GQA is mainly a computational-efficiency workaround for MHA, ablation studies (such as those in the [original GQA paper](https://arxiv.org/abs/2305.13245) and the [Llama 2 paper](https://arxiv.org/abs/2307.09288)) show it performs comparably to standard MHA in terms of LLM modeling performance.\\n\\nHowever, this assumes that the number of key-value groups is chosen carefully. In the extreme case where all attention heads share a single key-value group, known as multi-query attention, the memory usage decreases even more drastically but modeling performance can suffer. (And, on the other extreme, if we set the number of key-value groups equal to the number of query heads, we are back at standard multi-head attention.)\\n\\n&nbsp;\\n## GQA Memory Savings\\n\\nThe memory savings are mostly reflected in the KV storage. We can compute the KV storage size with the following formula:\\n\\nbytes \u2248 batch_size \u00d7 seqlen \u00d7 (embed_dim / n_heads) \u00d7 n_layers \u00d7 2 (K,V) \u00d7 bytes_per_elem \u00d7 n_kv_heads\\n\\nYou can use the [memory_estimator_gqa.py](memory_estimator_gqa.py) script in this folder to apply this for different model configs to see how much memory you can save by using GQA over MHA:\\n\\n```bash\\n\u279c uv run memory_estimator_gqa.py \\\\\\n  --emb_dim 4096 --n_heads 32 --n_layers 32 \\\\\\n  --context_length 32768 --n_kv_groups 4 \\\\\\n  --batch_size 1 --dtype bf16\\n==== Config ====\\ncontext_length   : 32768\\nemb_dim          : 4096\\nn_heads          : 32\\nn_layers         : 32\\nn_kv_groups      : 4\\nbatch_size       : 1\\ndtype            : bf16 (2 Bytes/elem)\\nhead_dim         : 128\\nGQA n_kv_heads   : 8\\n\\n==== KV-cache totals across all layers ====\\nMHA total KV cache  : 17.18 GB\\nGQA total KV cache  : 4.29 GB\\nRatio (MHA / GQA)   : 4.00x\\nSavings (GQA vs MHA): 75.00%\\n```\\n\\nThe savings when using GQA over MHA are further shown in the plot below for different key-value group sizes as a function of the context length:\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gqa-memory/3.webp?4\\\" alt=\\\"GQA\\\" width=\\\"500px\\\" />\\n\\n&nbsp;\\n\\nYou can reproduce the plot via `uv run plot_memory_estimates_gqa.py`.\\n\\n&nbsp;\\n## GQA Code Examples\\n\\nThe [gpt_with_kv_mha.py](gpt_with_kv_mha.py) and [gpt_with_kv_gqa.py](gpt_with_kv_gqa.py) scripts in this folder provide hands-on examples for comparing the MHA and GQA memory usage in the context of a GPT model implementation.\\n\\nNote that GQA is also used in the [Llama 3](../../ch05/07_gpt_to_llama), [Gemma 3](../../ch05/12_gemma3), and [Qwen3](../../ch05/11_qwen3) bonus materials. However, for simplicity, the code scripts in this folder modify the GPT architecture, which traditionally didn't use GQA.\\n\\nNote that the model is not trained and thus generates nonsensical text. However, you can use it as a drop-in replacement for the standard GPT model in chapters 5-7 and train it.\\n\\nAlso, this implementation uses the KV cache explained in [another bonus section](../03_kv-cache) so the memory savings are more pronounced.\\n\\n```bash\\nuv run gpt_with_kv_mha.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12\\n\\n...\\n\\nTime: 453.81 sec\\n72 tokens/sec\\nMax memory allocated: 1.54 GB\\n```\\n\\n```bash\\nuv run gpt_with_kv_gqa.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--n_kv_groups 4\\n\\n...\\n\\nTime: 516.33 sec\\n63 tokens/sec\\nMax memory allocated: 0.63 GB\\n```\\n\\nThe reason why we are not seeing such a big saving as in the plots above is 2-fold:\\n\\n1. I use a smaller configuration to have the model finish the generation in a reasonable time.\\n2. More importantly, we are looking at the whole model here, not just the attention mechanism; the fully-connected layers in the model take up most of the memory (but this is a topic for a separate analysis).\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/04_gqa/gpt_with_kv_gqa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f129c693aefc2671a6d68b4df1e66996e9d9fe5fd42ac47623235e9f8dc2c0e1\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4, adapted to use Grouped-Query Attention (GQA).\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# NEW: GQA instead of MHA\\n#####################################\\nclass GroupedQueryAttention(nn.Module):\\n    def __init__(\\n            self, d_in, d_out, dropout, num_heads, num_kv_groups, dtype=None, qkv_bias=False\\n    ):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n        assert num_heads % num_kv_groups == 0, \\\"num_heads must be divisible by num_kv_groups\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n\\n        self.W_key = nn.Linear(d_in, num_kv_groups * self.head_dim, bias=qkv_bias, dtype=dtype)\\n        self.W_value = nn.Linear(d_in, num_kv_groups * self.head_dim, bias=qkv_bias, dtype=dtype)\\n        self.num_kv_groups = num_kv_groups\\n        self.group_size = num_heads // num_kv_groups\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias, dtype=dtype)\\n        self.out_proj = nn.Linear(d_out, d_out, bias=False, dtype=dtype)\\n        self.dropout = nn.Dropout(dropout)\\n\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, _ = x.shape\\n\\n        # Apply projections\\n        queries = self.W_query(x)  # (b, num_tokens, num_heads * head_dim)\\n        keys = self.W_key(x)       # (b, num_tokens, num_kv_groups * head_dim)\\n        values = self.W_value(x)   # (b, num_tokens, num_kv_groups * head_dim)\\n\\n        # Reshape\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim).transpose(1, 2)\\n        keys_new = keys.view(b, num_tokens, self.num_kv_groups, self.head_dim).transpose(1, 2)\\n        values_new = values.view(b, num_tokens, self.num_kv_groups, self.head_dim).transpose(1, 2)\\n\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=2)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=2)\\n            keys_base, values_base = self.cache_k, self.cache_v\\n        else:\\n            keys_base, values_base = keys_new, values_new\\n            if self.cache_k is not None or self.cache_v is not None:\\n                self.cache_k, self.cache_v = None, None\\n                self.ptr_current_pos = 0\\n\\n        # Expand keys and values to match the number of heads\\n        # Shape: (b, num_heads, num_tokens, head_dim)\\n        keys = keys_base.repeat_interleave(self.group_size, dim=1)  # Shape: (b, num_heads, num_tokens, head_dim)\\n        values = values_base.repeat_interleave(self.group_size, dim=1)  # Shape: (b, num_heads, num_tokens, head_dim)\\n        # For example, before repeat_interleave along dim=1 (query groups):\\n        #   [K1, K2]\\n        # After repeat_interleave (each query group is repeated group_size times):\\n        #   [K1, K1, K2, K2]\\n        # If we used regular repeat instead of repeat_interleave, we'd get:\\n        #   [K1, K2, K1, K2]\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        # Shape: (b, num_heads, num_tokens, num_tokens)\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores = attn_scores.masked_fill(mask, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        assert keys.shape[-1] == self.head_dim\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = GroupedQueryAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            num_kv_groups=cfg[\\\"n_kv_groups\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Run GPT with grouped-query attention.\\\")\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--n_kv_groups\\\", type=int, default=2, help=\\\"Number of key/value groups.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n        \\\"n_kv_groups\\\": args.n_kv_groups\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/04_gqa/gpt_with_kv_mha.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"71a9f19168923d8fbd5d25e702ada4b33acd5867cc4352fc300772978017866d\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n            keys, values = self.cache_k, self.cache_v\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Run GPT with standard multi-head attention.\\\")\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/04_gqa/memory_estimator_gqa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"955289d2ed4f2810e6ca6078090945159d3fae5e06685031a4cd1e9eb7594ab5\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# KV-cache memory estimator for MHA vs GQA\\n\\n\\nimport argparse\\nimport math\\n\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes(n):\\n    gb = n / (1000 ** 3)\\n    return f\\\"{gb:,.2f} GB\\\"\\n\\n\\ndef calc_kv_bytes_total(batch, context_length, emb_dim, n_heads,\\n                             n_kv_heads, n_layers, bytes_per_elem):\\n    head_dim = math.ceil(emb_dim / n_heads)\\n    per_layer = batch * context_length * head_dim * n_kv_heads * 2 * bytes_per_elem\\n    return per_layer * n_layers\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Estimate KV-cache memory for MHA vs GQA\\\")\\n    p.add_argument(\\\"--context_length\\\", default=1024, type=int)\\n    p.add_argument(\\\"--emb_dim\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_heads\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_layers\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_kv_groups\\\", required=True, type=int)\\n    p.add_argument(\\\"--batch_size\\\", default=1, type=int)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"fp16\\\")\\n    args = p.parse_args()\\n\\n    cfg = {\\n        \\\"context_length\\\": args.context_length,\\n        \\\"emb_dim\\\": args.emb_dim,\\n        \\\"n_heads\\\": args.n_heads,\\n        \\\"n_layers\\\": args.n_layers,\\n        \\\"n_kv_groups\\\": args.n_kv_groups,\\n    }\\n\\n    if cfg[\\\"n_heads\\\"] % cfg[\\\"n_kv_groups\\\"] != 0:\\n        raise ValueError(\\\"n_kv_groups must divide n_heads exactly.\\\")\\n\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n    head_dim = math.ceil(cfg[\\\"emb_dim\\\"] / cfg[\\\"n_heads\\\"])\\n\\n    n_kv_heads_mha = cfg[\\\"n_heads\\\"]\\n    n_kv_heads_gqa = cfg[\\\"n_heads\\\"] // cfg[\\\"n_kv_groups\\\"]\\n\\n    total_mha = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_mha,\\n        cfg[\\\"n_layers\\\"],\\n        bytes_per_elem,\\n    )\\n\\n    total_gqa = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_gqa,\\n        cfg[\\\"n_layers\\\"],\\n        bytes_per_elem,\\n    )\\n\\n    ratio = total_mha / total_gqa\\n    savings = 1 - (total_gqa / total_mha)\\n\\n    print(\\\"==== Config ====\\\")\\n    for k, v in cfg.items():\\n        print(f\\\"{k:17}: {v}\\\")\\n    print(f\\\"batch_size       : {args.batch_size}\\\")\\n    print(f\\\"dtype            : {args.dtype} ({bytes_per_elem} Bytes/elem)\\\")\\n    print(f\\\"head_dim         : {head_dim}\\\")\\n    print(f\\\"GQA n_kv_heads   : {n_kv_heads_gqa}\\\")\\n    print()\\n\\n    print(\\\"==== KV-cache totals across all layers ====\\\")\\n    print(f\\\"MHA total KV cache  : {convert_bytes(total_mha)}\\\")\\n    print(f\\\"GQA total KV cache  : {convert_bytes(total_gqa)}\\\")\\n    print(f\\\"Ratio (MHA / GQA)   : {ratio:,.2f}x\\\")\\n    print(f\\\"Savings (GQA vs MHA): {savings*100:,.2f}%\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/04_gqa/plot_memory_estimates_gqa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"77706acf889eeb4b28fc1f5549037310ad3d73e01be579c96a1ba622cdcc298d\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# Plot KV-cache vs context length for different n_kv_groups\\n\\nimport matplotlib.pyplot as plt\\n\\n# Import from ./memory_estimator.py\\nfrom memory_estimator_gqa import calc_kv_bytes_total, DTYPE_BYTES\\n\\n\\ndef bytes_convert(n):\\n    gb = n / (1000 ** 3)\\n    return f\\\"{gb:.2f}\\\"\\n\\n\\ndef savings_percent(total_mha, total_gqa):\\n    return (1.0 - (total_gqa / total_mha)) * 100.0\\n\\n\\ndef plot_abs_kv_vs_context_multi_groups():\\n    n_heads = 24\\n    emb_dim = 2048\\n    n_layers = 48\\n    batch_size = 1\\n    dtype = \\\"bf16\\\"\\n    bytes_per_elem = DTYPE_BYTES[dtype]\\n\\n    # x-axis (log scale)\\n    context_lengths = [\\n        256, 512, 1024, 2048, 4096, 8192,\\n        16384, 32768, 65536, 131072\\n    ]\\n\\n    mha_gb = []\\n    for L in context_lengths:\\n        total_mha = calc_kv_bytes_total(\\n            batch_size, L, emb_dim, n_heads,\\n            n_heads,  # MHA: n_kv_heads = n_heads\\n            n_layers, bytes_per_elem\\n        )\\n        mha_gb.append(float(bytes_convert(total_mha)))\\n\\n    plt.figure()\\n    plt.plot(context_lengths, mha_gb, marker=\\\"o\\\", label=\\\"MHA (KV total)\\\")\\n\\n    # GQA curves for selected n_kv_groups\\n    groups_list = [4, 8, 12, 24]\\n    for g in groups_list:\\n        n_kv_heads = n_heads // g\\n        gqa_gb = []\\n        for L in context_lengths:\\n            total_gqa = calc_kv_bytes_total(\\n                batch_size, L, emb_dim, n_heads,\\n                n_kv_heads, n_layers, bytes_per_elem\\n            )\\n            gqa_gb.append(float(bytes_convert(total_gqa)))\\n\\n        # Compression rate relative to MHA\\n        comp = (n_heads / n_kv_heads) if n_kv_heads > 0 else float(\\\"inf\\\")\\n        plt.plot(context_lengths, gqa_gb, marker=\\\"o\\\",\\n                 label=f\\\"GQA (n_kv_groups={g}, {comp:,.1f}\u00d7 compression)\\\")\\n\\n    plt.xscale(\\\"log\\\")\\n    plt.xlabel(\\\"context_length (log scale)\\\")\\n    plt.ylabel(\\\"Total KV cache (GB)\\\")\\n    plt.title(\\n        \\\"KV-cache vs Context Length \u2014 MHA vs GQA (multi-group)\\\\n\\\"\\n        \\\"(n_heads=24, emb_dim=2048, n_layers=48, batch=1, dtype=bf16)\\\",\\n        fontsize=8\\n    )\\n    plt.grid(True, which=\\\"both\\\")\\n    plt.legend()\\n    plt.tight_layout()\\n    plt.savefig(\\\"kv_bytes_vs_context_length.pdf\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    plot_abs_kv_vs_context_multi_groups()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/05_mla/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ac43479cfe7b59bfdb76d212ce81c958bf7ab9b4c846b78e83eaf04a2128836e\",\"content\":\"# Multi-Head Latent Attention (MLA)\\n\\nThis bonus material illustrates the memory savings when using Multi-Head Latent Attention (MLA) over regular Multi-Head Attention (MHA).\\n\\n&nbsp;\\n## Introduction\\n\\nIn [../04_gqa](../04_gqa), we discussed Grouped-Query Attention (GQA) as a computational-efficiency workaround for MHA. And ablation studies (such as those in the[ original GQA paper](https://arxiv.org/abs/2305.13245) and the [Llama 2 paper](https://arxiv.org/abs/2307.09288)) show it performs comparably to standard MHA in terms of LLM modeling performance.\\n\\nNow, Multi-Head Latent Attention (MLA), which is used in [DeepSeek V2, V3, and R1](https://arxiv.org/abs/2412.19437), offers a different memory-saving strategy that also pairs particularly well with KV caching. Instead of sharing key and value heads like GQA, MLA compresses the key and value tensors into a lower-dimensional space before storing them in the KV cache. \\n\\nAt inference time, these compressed tensors are projected back to their original size before being used, as shown in the figure below. This adds an extra matrix multiplication but reduces memory usage.\\n\\n&nbsp;\\n\\n![MLA](https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/mla-memory/1.webp)\\n\\n&nbsp;\\n\\n(As a side note, the queries are also compressed, but only during training, not inference.)\\n\\nBy the way, as mentioned earlier, MLA is not new in DeepSeek V3, as its [DeepSeek V2 predecessor](https://arxiv.org/abs/2405.04434) also used (and even introduced) it. Also, the V2 paper contains a few interesting ablation studies that may explain why the DeepSeek team chose MLA over GQA (see the figure below).\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/mla-memory/2.webp\\\" alt=\\\"GQA\\\" width=\\\"500px\\\" />\\n\\n&nbsp;\\n\\nAs shown in the figure above, GQA appears to perform worse than MHA, whereas MLA offers better modeling performance than MHA, which is likely why the DeepSeek team chose MLA over GQA. (It would have been interesting to see the \\\"KV Cache per Token\\\" savings comparison between MLA and GQA as well!)\\n\\nTo summarize this section, before we move on to the next architecture component, MLA is a clever trick to reduce KV cache memory use while even slightly outperforming MHA in terms of modeling performance.\\n\\n&nbsp;\\n## MLA Memory Savings\\n\\nThe memory savings are mostly reflected in the KV storage. We can compute the KV storage size with the following formula:\\n\\nbytes \u2248 batch_size \u00d7 seqlen \u00d7 n_layers \u00d7 latent_dim \u00d7 bytes_per_elem\\n\\nIn contrast, MHA KV cache memory is computed as follows:\\n\\nbytes \u2248 batch_size \u00d7 seqlen \u00d7 n_layers \u00d7 embed_dim \u00d7 2 (K,V) \u00d7 bytes_per_elem\\n\\nThis means, in MLA, we reduce \\\"embed_dim \u00d7 2 (K,V)\\\" to \\\"latent_dim\\\", since we only stored the compressed latent representation instead of the full key and value vectors as shown in the earlier figure above.\\n\\n\\n\\nYou can use the [memory_estimator_mla.py](memory_estimator_mla.py) script in this folder to apply this for different model configs to see how much memory you can save by using MLA over MHA:\\n\\n```bash\\n\u279c uv run memory_estimator_mla.py \\\\\\n  --context_length 8192 \\\\\\n  --emb_dim 2048 \\\\\\n  --n_heads 24 \\\\\\n  --n_layers 48 \\\\\\n  --n_kv_groups 4 \\\\\\n  --batch_size 1 \\\\\\n  --dtype bf16 \\\\\\n  --latent_dim 1024\\n==== Config ====\\ncontext_length   : 8192\\nemb_dim          : 2048\\nn_heads          : 24\\nn_layers         : 48\\nn_kv_groups      : 4\\nlatent_dim       : 1024\\nbatch_size       : 1\\ndtype            : bf16 (2 Bytes/elem)\\nhead_dim         : 86\\nGQA n_kv_heads   : 6\\n\\n==== KV-cache totals across all layers ====\\nMHA total KV cache  : 3.25 GB\\nGQA total KV cache  : 0.81 GB\\nMLA total KV cache  : 0.81 GB\\nRatio (MHA / GQA)   : 4.00x\\nSavings (GQA vs MHA): 75.00%\\nRatio (MHA / MLA)   : 4.03x\\nSavings (MLA vs MHA): 75.19%\\n```\\n\\nNote that the compression above (`--emb_dim 2048 -> latent_dim 1024`) to achieve a similar saving as for GQA. In practice, the compression is a hyperparameter that needs to be carefully investigated, as choosing `latent_dim` to be too small can have negative impact on the modeling performance (similar to choosing too many `n_kv_groups` in GQA).\\n\\nThe savings when using MLA over MHA are further shown in the plot below for different `latent_dim` values as a function of the context length:\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/mla-memory/3.webp?2\\\" alt=\\\"GQA\\\" width=\\\"500px\\\" />\\n\\n&nbsp;\\n\\nYou can reproduce the plot via `uv run plot_memory_estimates_mla.py`.\\n\\n\\n\\n&nbsp;\\n## MLA Code Examples\\n\\nThe [gpt_with_kv_mha.py](gpt_with_kv_mha.py) and [gpt_with_kv_mla.py](gpt_with_kv_mla.py) scripts in this folder provide hands-on examples for comparing the MHA and MLA memory usage in the context of a GPT model implementation. \\n\\nHere, the MLA code is inspired by the [https://huggingface.co/bird-of-paradise/deepseek-mla](https://huggingface.co/bird-of-paradise/deepseek-mla) implementation.\\n\\nNote that MLA can also be used in combination with [GQA](../04_gqa), but for simplicity, I this is not done here. (Currently, I am also not aware of a prominent LLM doing this.)\\n\\nAlso note that the model is not trained and thus generates nonsensical text. However, you can use it as a drop-in replacement for the standard GPT model in chapters 5-7 and train it.\\n\\nLastly, this implementation uses the KV cache explained in [another bonus section](../03_kv-cache) so the memory savings are more pronounced.\\n\\n```bash\\nuv run gpt_with_kv_mha.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 768\\n\\n...\\n\\nTime: 453.81 sec\\n72 tokens/sec\\nMax memory allocated: 1.54 GB\\n```\\n\\n```bash\\nuv run gpt_with_kv_mla.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 768 \\\\\\n--latent_dim 192 # (768\u00d72)/192 = 8\u00d7 compression\\n\\n...\\n\\nTime: 487.21 sec\\n67 tokens/sec\\nMax memory allocated: 0.68 GB\\n```\\n\\nThe reason why we are not seeing such a big saving as in the plots above is 2-fold:\\n\\n1. I use a smaller configuration to have the model finish the generation in a reasonable time.\\n2. More importantly, we are looking at the whole model here, not just the attention mechanism; the fully-connected layers in the model take up most of the memory (but this is a topic for a separate analysis).\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/05_mla/gpt_with_kv_mha.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c6b2d294aabaf9aa8615fa56f1d490e6abdbe3c1b4e09bd65c0010f3e1b6f6f5\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n            keys, values = self.cache_k, self.cache_v\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n         #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Run GPT with standard multi-head attention.\\\")\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/05_mla/gpt_with_kv_mla.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aded18dd5e48c05b2be537afc79c475edd485cecbc19b7fa70450e3b9f10f29c\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4, adapted to use Multi-Head Latent Attention (MLA).\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Multi-Head Latent Attention\\n#####################################\\n# The MLA code below is inspired by\\n# https://huggingface.co/bird-of-paradise/deepseek-mla\\n\\n\\nclass MultiHeadLatentAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads,\\n                 qkv_bias=False, latent_dim=None):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n        self.latent_dim = latent_dim if latent_dim is not None else max(16, d_out // 8)\\n\\n        # Projections\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)              # per-head Q\\n        self.W_DKV = nn.Linear(d_in, self.latent_dim, bias=qkv_bias)    # down to latent C\\n        self.W_UK = nn.Linear(self.latent_dim, d_out, bias=qkv_bias)   # latent -> per-head K\\n        self.W_UV = nn.Linear(self.latent_dim, d_out, bias=qkv_bias)   # latent -> per-head V\\n\\n        self.out_proj = nn.Linear(d_out, d_out)\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # Latent-KV cache\\n        self.register_buffer(\\\"cache_c_kv\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def reset_cache(self):\\n        self.cache_c_kv = None\\n        self.ptr_current_pos = 0\\n\\n    @staticmethod\\n    def _reshape_to_heads(x, num_heads, head_dim):\\n        # (b, T, d_out) -> (b, num_heads, T, head_dim)\\n        bsz, num_tokens, _ = x.shape\\n        return x.view(bsz, num_tokens, num_heads, head_dim).transpose(1, 2).contiguous()\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, _ = x.shape\\n        num_heads = self.num_heads\\n        head_dim = self.head_dim\\n\\n        # 1) Project to queries (per-token, per-head) and new latent chunk\\n        queries_all = self.W_query(x)  # (b, T, d_out)\\n        latent_new = self.W_DKV(x)  # (b, T, latent_dim)\\n\\n        # 2) Update latent cache and choose latent sequence to up-project\\n        if use_cache:\\n            if self.cache_c_kv is None:\\n                latent_total = latent_new\\n            else:\\n                latent_total = torch.cat([self.cache_c_kv, latent_new], dim=1)\\n            self.cache_c_kv = latent_total\\n        else:\\n            latent_total = latent_new\\n\\n        # 3) Up-project latent to per-head keys/values (then split into heads)\\n        keys_all = self.W_UK(latent_total)   # (b, T_k_total, d_out)\\n        values_all = self.W_UV(latent_total)   # (b, T_k_total, d_out)\\n\\n        # 4) Reshape to heads\\n        queries = self._reshape_to_heads(queries_all, num_heads, head_dim)\\n        keys = self._reshape_to_heads(keys_all, num_heads, head_dim)\\n        values = self._reshape_to_heads(values_all, num_heads, head_dim)\\n\\n        # 5) Scaled dot-product attention with causal mask\\n        attn_scores = torch.matmul(queries, keys.transpose(-2, -1))\\n\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadLatentAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"],\\n            latent_dim=cfg[\\\"latent_dim\\\"])\\n\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        #  KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    #  KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Run GPT with standard multi-head attention.\\\")\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n    parser.add_argument(\\\"--latent_dim\\\", type=int, default=None,\\n        help=\\\"Latent dim for MLA\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n        \\\"latent_dim\\\": args.latent_dim,\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/05_mla/memory_estimator_mla.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4817cfaf2714202a8cd59347d431de0948bf5da0f6d167cf2c117a26bacd321b\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n#\\n# KV-cache memory estimator for MHA vs GQA vs MLA\\n\\nimport argparse\\nimport math\\n\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes(n):\\n    gb = n / (1000 ** 3)\\n    return f\\\"{gb:,.2f} GB\\\"\\n\\n\\ndef calc_kv_bytes_total(batch, context_length, emb_dim, n_heads,\\n                             n_kv_heads, n_layers, bytes_per_elem):\\n    # Generic KV-cache: per-head dim is embed_dim / n_heads, times 2 for K and V\\n    head_dim = math.ceil(emb_dim / n_heads)\\n    per_layer = batch * context_length * head_dim * n_kv_heads * 2 * bytes_per_elem\\n    return per_layer * n_layers\\n\\n\\ndef calc_mla_bytes_total(batch, context_length, n_layers, latent_dim, bytes_per_elem):\\n    # Simple MLA (per-token compressed latent)\\n    # bytes \u2248 batch \u00d7 seqlen \u00d7 n_layers \u00d7 latent_dim \u00d7 bytes_per_elem\\n    return batch * context_length * n_layers * latent_dim * bytes_per_elem\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Estimate KV-cache memory for MHA vs GQA vs MLA\\\")\\n    p.add_argument(\\\"--context_length\\\", default=1024, type=int)\\n    p.add_argument(\\\"--emb_dim\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_heads\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_layers\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_kv_groups\\\", required=True, type=int)\\n    p.add_argument(\\\"--latent_dim\\\", required=True, type=int, help=\\\"MLA per-token latent dimension\\\")\\n    p.add_argument(\\\"--batch_size\\\", default=1, type=int)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"fp16\\\")\\n    args = p.parse_args()\\n\\n    cfg = {\\n        \\\"context_length\\\": args.context_length,\\n        \\\"emb_dim\\\": args.emb_dim,\\n        \\\"n_heads\\\": args.n_heads,\\n        \\\"n_layers\\\": args.n_layers,\\n        \\\"n_kv_groups\\\": args.n_kv_groups,\\n        \\\"latent_dim\\\": args.latent_dim,\\n    }\\n\\n    if cfg[\\\"n_heads\\\"] % cfg[\\\"n_kv_groups\\\"] != 0:\\n        raise ValueError(\\\"n_kv_groups must divide n_heads exactly.\\\")\\n\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n    head_dim = math.ceil(cfg[\\\"emb_dim\\\"] / cfg[\\\"n_heads\\\"])\\n\\n    n_kv_heads_mha = cfg[\\\"n_heads\\\"]\\n    n_kv_heads_gqa = cfg[\\\"n_heads\\\"] // cfg[\\\"n_kv_groups\\\"]\\n\\n    total_mha = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_mha,\\n        cfg[\\\"n_layers\\\"],\\n        bytes_per_elem,\\n    )\\n\\n    total_gqa = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_gqa,\\n        cfg[\\\"n_layers\\\"],\\n        bytes_per_elem,\\n    )\\n\\n    total_mla = calc_mla_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"n_layers\\\"],\\n        cfg[\\\"latent_dim\\\"],\\n        bytes_per_elem,\\n    )\\n\\n    ratio = total_mha / total_gqa if total_gqa != 0 else float(\\\"inf\\\")\\n    savings = 1 - (total_gqa / total_mha) if total_mha != 0 else 0.0\\n\\n    ratio_mha_mla = total_mha / total_mla if total_mla != 0 else float(\\\"inf\\\")\\n    savings_mla = 1 - (total_mla / total_mha) if total_mha != 0 else 0.0\\n\\n    print(\\\"==== Config ====\\\")\\n    for k, v in cfg.items():\\n        print(f\\\"{k:17}: {v}\\\")\\n    print(f\\\"batch_size       : {args.batch_size}\\\")\\n    print(f\\\"dtype            : {args.dtype} ({bytes_per_elem} Bytes/elem)\\\")\\n    print(f\\\"head_dim         : {head_dim}\\\")\\n    print(f\\\"GQA n_kv_heads   : {n_kv_heads_gqa}\\\")\\n    print()\\n\\n    print(\\\"==== KV-cache totals across all layers ====\\\")\\n    print(f\\\"MHA total KV cache  : {convert_bytes(total_mha)}\\\")\\n    print(f\\\"GQA total KV cache  : {convert_bytes(total_gqa)}\\\")\\n    print(f\\\"MLA total KV cache  : {convert_bytes(total_mla)}\\\")\\n    print(f\\\"Ratio (MHA / GQA)   : {ratio:,.2f}x\\\")\\n    print(f\\\"Savings (GQA vs MHA): {savings*100:,.2f}%\\\")\\n    print(f\\\"Ratio (MHA / MLA)   : {ratio_mha_mla:,.2f}x\\\")\\n    print(f\\\"Savings (MLA vs MHA): {savings_mla*100:,.2f}%\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/05_mla/plot_memory_estimates_mla.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b034acbeeece8641490b320f390dcba300c7611c6d3bb83731bb400b46948a0d\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport matplotlib.pyplot as plt\\n\\n# Bytes per element\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes_to_gb(n_bytes):\\n    return n_bytes / (1000. ** 3)\\n\\n\\ndef calc_kv_bytes_total_mha(batch, context_length, emb_dim, n_heads,\\n                                 n_layers, bytes_per_elem):\\n    head_dim = emb_dim / n_heads\\n    per_layer = batch * context_length * head_dim * n_heads * 2 * bytes_per_elem\\n    return per_layer * n_layers\\n\\n\\ndef calc_kv_bytes_total_mla(batch, context_length, n_layers, latent_dim, bytes_per_elem):\\n    return batch * context_length * n_layers * latent_dim * bytes_per_elem\\n\\n\\ndef plot_abs_kv_vs_context_multiple():\\n    n_heads = 24\\n    emb_dim = 2048\\n    n_layers = 48\\n    batch_size = 1\\n    dtype = \\\"bf16\\\"\\n    bytes_per_elem = DTYPE_BYTES[dtype]\\n\\n    context_lengths = [\\n        256, 512, 1024, 2048, 4096, 8192,\\n        16384, 32768, 65536, 131072\\n    ]\\n\\n    mha_gb = []\\n    for L in context_lengths:\\n        total_mha = calc_kv_bytes_total_mha(\\n            batch_size, L, emb_dim, n_heads, n_layers, bytes_per_elem\\n        )\\n        mha_gb.append(convert_bytes_to_gb(total_mha))\\n\\n    latent_dims = [1024, 512, 256, 64]\\n    plt.figure()\\n    plt.plot(context_lengths, mha_gb, marker=\\\"o\\\", label=\\\"MHA (KV total)\\\")\\n\\n    L_ref = context_lengths[-1]\\n    total_mha_ref = calc_kv_bytes_total_mha(batch_size, L_ref, emb_dim, n_heads, n_layers, bytes_per_elem)\\n\\n    for latent_dim in latent_dims:\\n        mla_gb = []\\n        for L in context_lengths:\\n            total_mla = calc_kv_bytes_total_mla(\\n                batch_size, L, n_layers, latent_dim, bytes_per_elem\\n            )\\n            mla_gb.append(convert_bytes_to_gb(total_mla))\\n\\n        total_mla_ref = calc_kv_bytes_total_mla(batch_size, L_ref, n_layers, latent_dim, bytes_per_elem)\\n        comp = total_mha_ref / total_mla_ref if total_mla_ref != 0 else float(\\\"inf\\\")\\n\\n        plt.plot(context_lengths, mla_gb, marker=\\\"o\\\",\\n                 label=f\\\"MLA (latent_dim={latent_dim}, {comp:,.1f}\u00d7 compression)\\\")\\n\\n    plt.xscale(\\\"log\\\")\\n    plt.xlabel(\\\"context_length (log scale)\\\")\\n    plt.ylabel(\\\"Total KV cache (GB)\\\")\\n    plt.title(\\n        \\\"KV-cache vs Context Length \u2014 MHA vs MLA\\\\n\\\"\\n        f\\\"(n_heads={n_heads}, emb_dim={emb_dim}, n_layers={n_layers}, \\\"\\n        f\\\"batch={batch_size}, dtype={dtype})\\\",\\n        fontsize=8\\n    )\\n    plt.grid(True, which=\\\"both\\\")\\n    plt.legend()\\n    plt.tight_layout()\\n    plt.savefig(\\\"kv_bytes_vs_context_length.pdf\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    plot_abs_kv_vs_context_multiple()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/06_swa/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"46f455ffb1a62c051846337b633ad37b8f667168d94ffe76eb8514c9d14b6903\",\"content\":\"# Sliding Window Attention (SWA)\\n\\nThis bonus material illustrates the memory savings when using Sliding Window Attention (SWA) over regular Multi-Head Attention (MHA).\\n\\n\\n\\n&nbsp;\\n## Introduction\\n\\nWhat is sliding window attention (SWA)? If we think of regular self-attention as a *global* attention mechanism, since each sequence element can access every other sequence element, then we can think of SWA as *local* attention, because here we restrict the context size around the current query position. This is illustrated in the figure below.\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/swa-memory/1.webp?2\\\" alt=\\\"Sliding Window Attention\\\" width=\\\"500px\\\" />\\n\\nAs shown in the figure above, instead of attending to all previous tokens, each token only attends to a fixed-size local window around its position. This localized attention lowers the size of the KV cache substantially.\\n\\nIn the remainder of this introduction, we will discuss SWA in the context of [Gemma 3](https://arxiv.org/abs/2503.19786), which is implemented from scratch in [../../ch05/12_gemma3](../../ch05/12_gemma3).\\n\\nSliding window attention was originally introduced in the [LongFormer paper in 2020](https://arxiv.org/abs/2004.05150), but the reason we focus on Google's Gemma models is that they are very good open-weight models showing that sliding window attention is indeed a feasible approach in recent, capable models.\\n\\n[Gemma 2](https://arxiv.org/abs/2408.00118) used a hybrid approach that combined local (sliding window) and global attention layers in a 1:1 ratio. Each token could attend to a context window of 4 k tokens. The reason for this 1:1 hybrid is that it strikes a balance between efficiency and global context modeling, since an LLM using only local attention can be too restrictive.\\n\\n[Gemma 3](https://arxiv.org/abs/2503.19786) then took the design further toward efficiency. It used a 5:1 ratio between sliding window and full attention layers, which means that for every five local attention layers, there is one global layer. In addition, the sliding window size was reduced from 4096 tokens in Gemma 2 to 1024 tokens in Gemma 3. \\n\\nInterestingly, the ablation studies in the Gemma 3 technical report indicate that these changes have only a minor effect on overall model quality. In other words, the substantial memory and compute savings achieved through sliding window attention come with minimal loss in modeling performance.\\n\\n\\n\\n&nbsp;\\n## Sliding Window Attention (SWA) Memory Savings\\n\\nThe memory savings are mostly reflected in the KV storage. We can compute the KV storage size with the following formula:\\n\\nbytes \u2248 batch_size \u00d7 seqlen \u00d7 (embed_dim / n_heads) \u00d7 n_layers \u00d7 2 (K,V) \u00d7 bytes_per_elem \u00d7 n_kv_heads\\n\\nWhen using SWA, we replace the sequence length (seqlen) above by the window size W. So, when using sliding window attention, we reduce the KV cache size by a factor of \\\"W / seqlen\\\". (Note that for simplicity, this assumes that sliding window attention is used in every layer.)\\n\\n\\nYou can use the [memory_estimator_swa.py](memory_estimator_swa.py) script in this folder to apply this for different model configs to see how much memory you can save by using SWA over MHA:\\n\\n```bash\\n\u279c uv run memory_estimator_swa.py \\\\\\n  --emb_dim 4096 --n_heads 32 --n_layers 32 \\\\\\n  --context_length 32768 --n_kv_groups 4 \\\\\\n  --batch_size 1 --dtype bf16 \\\\\\n  --sliding_window_size 1024 --swa_ratio \\\"5:1\\\"\\n==== Config ====\\ncontext_length         : 32768\\nsliding_window_size    : 1024\\nemb_dim                : 4096\\nn_heads                : 32\\nn_layers               : 32\\nn_kv_groups            : 4\\nbatch_size             : 1\\ndtype                  : bf16 (2 Bytes/elem)\\nhead_dim               : 128\\nGQA n_kv_heads         : 8\\nEffective SWA window W : 1024\\nLayer ratio (SWA:Full) : 5:1\\nDistributed layers     : 27 SWA, 5 FULL\\n\\n==== KV-cache totals across all layers ====\\nMHA KV total           : 17.18 GB\\nGQA KV total           : 4.29 GB\\nMHA + SWA (Ratio: 5:1) : 3.14 GB\\nGQA + SWA (Ratio: 5:1) : 0.78 GB\\n```\\n\\nNote that Gemma 3 uses SWA in combination with GQA.\\n\\nThe savings when using SWA over MHA are further shown in the plot below for different context lengths:\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/swa-memory/4.webp?2\\\" alt=\\\"SWA\\\" width=\\\"800px\\\" />\\n\\n&nbsp;\\n\\nYou can reproduce thi plots via:\\n\\n```bash\\nuv run plot_memory_estimates_swa.py \\\\\\n  --emb_dim 4096 --n_heads 48 --n_layers 36 \\\\\\n  --batch_size 1 --dtype bf16 \\\\\\n  --sliding_window_size 2048 --swa_ratio \\\"5:1\\\"\\n```\\n\\n\\n&nbsp;\\n## SWA Code Examples\\n\\nThe [gpt_with_kv_mha.py](gpt_with_kv_mha.py) and [gpt_with_kv_swa.py](gpt_with_kv_swa.py) scripts in this folder provide hands-on examples for comparing the MHA and SWA memory usage in the context of a GPT model implementation.\\n\\nNote that SWA can also be used in combination with MLA and GQA (as mentioned earlier), but for simplicity, this is not done here.\\n\\nNote that the model is not trained and thus generates nonsensical text. However, you can use it as a drop-in replacement for the standard GPT model in chapters 5-7 and train it.\\n\\nAlso, this implementation uses the KV cache explained in [another bonus section](../03_kv-cache), so the memory savings are more pronounced.\\n\\n```bash\\nuv run gpt_with_kv_mha.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 768\\n\\n...\\n\\nTime: 453.81 sec\\n72 tokens/sec\\nMax memory allocated: 1.54 GB\\n```\\n\\n```bash\\nuv run gpt_with_kv_swa.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 768 \\\\\\n--sliding_window_size 1024 \\\\\\n--sliding_window_stride 5   # like Gemma 3\\n\\n...\\n\\nTime: 514.38 sec\\n63 tokens/sec\\nMax memory allocated: 0.63 GB\\n```\\n\\nThe reason why we are not seeing such a big saving as in the plots above is 2-fold:\\n\\n1. I use a smaller configuration to have the model finish the generation in a reasonable time.\\n2. More importantly, we are looking at the whole model here, not just the attention mechanism; the fully-connected layers in the model take up most of the memory (but this is a topic for a separate analysis).\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/06_swa/gpt_with_kv_mha.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"71a9f19168923d8fbd5d25e702ada4b33acd5867cc4352fc300772978017866d\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n            keys, values = self.cache_k, self.cache_v\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Run GPT with standard multi-head attention.\\\")\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/06_swa/gpt_with_kv_swa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5a5374633fd2b8d18519c6cb71c73aa465014319f4af61b7c9f5b5f9cda4393b\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttentionWithSWA(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False, sliding_window_size=None):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n        self.sliding_window_size = sliding_window_size\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            old_cache_k, old_cache_v = self.cache_k, self.cache_v\\n            old_len = 0 if old_cache_k is None else old_cache_k.size(1)\\n            if old_cache_k is None:\\n                combined_k, combined_v = keys_new, values_new\\n            else:\\n                combined_k = torch.cat([old_cache_k, keys_new], dim=1)\\n                combined_v = torch.cat([old_cache_v, values_new], dim=1)\\n\\n            keys, values = combined_k, combined_v\\n            if self.sliding_window_size is not None:\\n                # During chunked prefill we need up to W-1 older keys plus the whole\\n                # current chunk (so the earliest queries in the chunk keep their full\\n                # sliding-window context)\\n                attn_keep = min(keys.size(1), self.sliding_window_size + num_tokens - 1)\\n                keys = keys[:, -attn_keep:, :, :]\\n                values = values[:, -attn_keep:, :, :]\\n\\n                cache_keep = min(combined_k.size(1), self.sliding_window_size)\\n                self.cache_k = combined_k[:, -cache_keep:, :, :]\\n                self.cache_v = combined_v[:, -cache_keep:, :, :]\\n            else:\\n                self.cache_k, self.cache_v = combined_k, combined_v\\n\\n            dropped = combined_k.size(1) - keys.size(1)\\n            k_start_pos_abs = (self.ptr_current_pos - old_len) + dropped\\n            q_start_pos_abs = self.ptr_current_pos\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal + sliding-window mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        # Determine absolute positions for q and k\\n        if use_cache:\\n            q_start = q_start_pos_abs\\n            k_start = k_start_pos_abs\\n        else:\\n            q_start = 0\\n            k_start = 0\\n        q_positions = torch.arange(q_start, q_start + num_tokens_Q, device=device, dtype=torch.long)\\n        k_positions = torch.arange(k_start, k_start + num_tokens_K, device=device, dtype=torch.long)\\n        # Sliding window width\\n        W = num_tokens_K + 1 if self.sliding_window_size is None else int(self.sliding_window_size)\\n        diff = q_positions.unsqueeze(-1) - k_positions.unsqueeze(0)\\n        mask_bool = (diff < 0) | (diff >= W)\\n        if use_cache:\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            self.ptr_current_pos = 0\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttentionWithSWA(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"],\\n            sliding_window_size=cfg[\\\"sliding_window_size\\\"],\\n        )\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        blocks = []\\n        window_stride = cfg[\\\"sliding_window_stride\\\"]\\n        window_size = cfg[\\\"sliding_window_size\\\"] if \\\"sliding_window_size\\\" in cfg else None\\n        for i in range(cfg[\\\"n_layers\\\"]):\\n            blk = TransformerBlock(cfg)\\n            # K:1 schedule meaning that K SWA layers are followed by 1 regular layer\\n            K = int(window_stride)\\n            if K <= 0:\\n                # 0 => all regular; negative => all SWA\\n                use_swa = False if K == 0 else True\\n            else:\\n                group = K + 1\\n                use_swa = (i % group) < K\\n            blk.att.sliding_window_size = window_size if use_swa else None\\n            blocks.append(blk)\\n        self.trf_blocks = nn.ModuleList(blocks)\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Run GPT with standard multi-head attention.\\\")\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n    parser.add_argument(\\\"--sliding_window_size\\\", type=int, default=1024, help=\\\"Window size for sliding window attention.\\\")\\n    parser.add_argument(\\\"--sliding_window_stride\\\", type=int, default=2, help=\\\"K:1 frequency sliding window attention is applied. K=5 means 5 sliding window layers follows by a regular layer.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n        \\\"sliding_window_size\\\": args.sliding_window_size,\\n        \\\"sliding_window_stride\\\": args.sliding_window_stride\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/06_swa/memory_estimator_swa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"da47347545252a0a4064902f19fd408c4056773c884198a21c7556bf4774a3b6\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n#\\n# KV-cache memory estimator for MHA vs GQA with SWA.\\n\\nimport argparse\\nimport math\\n\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes(n):\\n    gb = n / (1000 ** 3)\\n    return f\\\"{gb:,.2f} GB\\\"\\n\\n\\ndef calc_kv_bytes_per_layer(batch, context_length, head_dim, n_kv_heads, bytes_per_elem):\\n    # KV = batch * tokens * head_dim * n_kv_heads * 2 (K,V) * bytes\\n    return batch * context_length * head_dim * n_kv_heads * 2 * bytes_per_elem\\n\\n\\ndef parse_ratio(ratio_str):\\n    # \\\"--swa_ratio a:b\\\" means a SWA layers for every b full layers within a block\\n    try:\\n        a_str, b_str = ratio_str.split(\\\":\\\")\\n        a, b = int(a_str), int(b_str)\\n        assert a >= 0 and b >= 0 and (a + b) > 0\\n        return a, b\\n    except Exception:\\n        raise ValueError(\\\"--swa_ratio must be in the form 'a:b' with nonnegative integers and a+b>0\\\")\\n\\n\\ndef distribute_layers(n_layers, a, b):\\n    block = a + b\\n    blocks = n_layers // block\\n    rem = n_layers % block\\n    swa = blocks * a + min(a, rem)\\n    full = blocks * b + max(0, rem - a)\\n    return swa, full\\n\\n\\ndef estimate_totals(context_length, sliding_window_size, emb_dim, n_heads, n_layers,\\n                    n_kv_groups, batch_size, dtype, swa_ratio):\\n    if n_heads % n_kv_groups != 0:\\n        raise ValueError(\\\"n_kv_groups must divide n_heads exactly.\\\")\\n\\n    bytes_per_elem = DTYPE_BYTES[dtype]\\n    head_dim = math.ceil(emb_dim / n_heads)\\n    n_kv_heads_mha = n_heads\\n    n_kv_heads_gqa = n_heads // n_kv_groups\\n\\n    a_swa, b_full = parse_ratio(swa_ratio)\\n    n_swa_layers, n_full_layers = distribute_layers(n_layers, a_swa, b_full)\\n\\n    eff_W = min(context_length, sliding_window_size)\\n    L = context_length\\n\\n    # Per-layer costs\\n    per_mha_full = calc_kv_bytes_per_layer(batch_size, L, head_dim, n_kv_heads_mha, bytes_per_elem)\\n    per_gqa_full = calc_kv_bytes_per_layer(batch_size, L, head_dim, n_kv_heads_gqa, bytes_per_elem)\\n    per_mha_swa = calc_kv_bytes_per_layer(batch_size, eff_W, head_dim, n_kv_heads_mha, bytes_per_elem)\\n    per_gqa_swa = calc_kv_bytes_per_layer(batch_size, eff_W, head_dim, n_kv_heads_gqa, bytes_per_elem)\\n\\n    # Totals\\n    total_mha_allfull = per_mha_full * n_layers\\n    total_gqa_allfull = per_gqa_full * n_layers\\n    total_mixed_mha = n_swa_layers * per_mha_swa + n_full_layers * per_mha_full\\n    total_mixed_gqa = n_swa_layers * per_gqa_swa + n_full_layers * per_gqa_full\\n\\n    return {\\n        \\\"bytes_per_elem\\\": bytes_per_elem,\\n        \\\"head_dim\\\": head_dim,\\n        \\\"n_kv_heads_gqa\\\": n_kv_heads_gqa,\\n        \\\"eff_W\\\": eff_W,\\n        \\\"n_swa_layers\\\": n_swa_layers,\\n        \\\"n_full_layers\\\": n_full_layers,\\n        \\\"total_mha_allfull\\\": total_mha_allfull,\\n        \\\"total_gqa_allfull\\\": total_gqa_allfull,\\n        \\\"total_mixed_mha\\\": total_mixed_mha,\\n        \\\"total_mixed_gqa\\\": total_mixed_gqa,\\n    }\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Estimate KV-cache memory for MHA/GQA with SWA layer ratio\\\")\\n    p.add_argument(\\\"--context_length\\\", default=1024, type=int)\\n    p.add_argument(\\\"--sliding_window_size\\\", required=True, type=int,\\n                   help=\\\"SWA window size W per SWA layer.\\\")\\n    p.add_argument(\\\"--emb_dim\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_heads\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_layers\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_kv_groups\\\", required=True, type=int,\\n                   help=\\\"GQA groups; 1 means MHA-equivalent KV heads.\\\")\\n    p.add_argument(\\\"--batch_size\\\", default=1, type=int)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"fp16\\\")\\n    p.add_argument(\\\"--swa_ratio\\\", default=\\\"1:0\\\",\\n                   help=\\\"SWA:Full layer ratio. Example '5:1' -> 5 SWA for each 1 full. \\\"\\n                        \\\"'1:5' -> 1 SWA for 5 full. Default '1:0' = all SWA.\\\")\\n    args = p.parse_args()\\n\\n    cfg = {\\n        \\\"context_length\\\": args.context_length,\\n        \\\"sliding_window_size\\\": args.sliding_window_size,\\n        \\\"emb_dim\\\": args.emb_dim,\\n        \\\"n_heads\\\": args.n_heads,\\n        \\\"n_layers\\\": args.n_layers,\\n        \\\"n_kv_groups\\\": args.n_kv_groups,\\n    }\\n\\n    res = estimate_totals(\\n        context_length=cfg[\\\"context_length\\\"],\\n        sliding_window_size=cfg[\\\"sliding_window_size\\\"],\\n        emb_dim=cfg[\\\"emb_dim\\\"],\\n        n_heads=cfg[\\\"n_heads\\\"],\\n        n_layers=cfg[\\\"n_layers\\\"],\\n        n_kv_groups=cfg[\\\"n_kv_groups\\\"],\\n        batch_size=args.batch_size,\\n        dtype=args.dtype,\\n        swa_ratio=args.swa_ratio,\\n    )\\n\\n    print(\\\"==== Config ====\\\")\\n    for k, v in cfg.items():\\n        print(f\\\"{k:23}: {v}\\\")\\n    print(f\\\"batch_size             : {args.batch_size}\\\")\\n    print(f\\\"dtype                  : {args.dtype} ({res['bytes_per_elem']} Bytes/elem)\\\")\\n    print(f\\\"head_dim               : {res['head_dim']}\\\")\\n    print(f\\\"GQA n_kv_heads         : {res['n_kv_heads_gqa']}\\\")\\n    print(f\\\"Effective SWA window W : {res['eff_W']}\\\")\\n    print(f\\\"Layer ratio (SWA:Full) : {args.swa_ratio} -> \\\"\\n          f\\\"{res['n_swa_layers']} SWA, {res['n_full_layers']} Full\\\")\\n    print()\\n\\n    print(\\\"==== KV-cache totals across all layers ====\\\")\\n    print(f\\\"MHA KV total           : {convert_bytes(res['total_mha_allfull'])}\\\")\\n    print(f\\\"GQA KV total           : {convert_bytes(res['total_gqa_allfull'])}\\\")\\n    print(f\\\"MHA + SWA (ratio {args.swa_ratio})  : {convert_bytes(res['total_mixed_mha'])}\\\")\\n    print(f\\\"GQA + SWA (ratio {args.swa_ratio})  : {convert_bytes(res['total_mixed_gqa'])}\\\")\\n    print()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/06_swa/plot_memory_estimates_swa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6ff408de2a2bf2bb0258444b47c8cfbd6ebf45f6c054e12f4c0edaab8e1466c0\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n#\\n# Sliding Window Attention (SWA) memory usage vs context length plot.\\n#\\n# This script mirrors the style and structure of plot_memory_estimates_mla.py.\\n\\nimport argparse\\nfrom pathlib import Path\\n\\nimport matplotlib.pyplot as plt\\nimport numpy as np\\n\\n\\n# Bytes per element\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes_to_gb(n_bytes):\\n    return n_bytes / (1000.0 ** 3)\\n\\n\\ndef parse_ratio(ratio_str):\\n    # \\\"--swa_ratio a:b\\\" means a SWA layers for every b full layers within a block\\n    try:\\n        a_str, b_str = ratio_str.split(\\\":\\\")\\n        a, b = int(a_str), int(b_str)\\n        assert a >= 0 and b >= 0 and (a + b) > 0\\n        return a, b\\n    except Exception:\\n        raise ValueError(\\\"--swa_ratio must be in the form 'a:b' with nonnegative integers and a+b>0\\\")\\n\\n\\ndef calc_kv_bytes_total_mha(batch, context_length, emb_dim, n_layers, bytes_per_elem):\\n    # For MHA, n_kv_heads = n_heads, which cancels out:\\n    # total = B * L * E * 2 (K,V) * bytes * n_layers\\n    return batch * context_length * emb_dim * 2 * bytes_per_elem * n_layers\\n\\n\\ndef calc_kv_bytes_total_gqa(\\n    batch, context_length, emb_dim, n_layers, bytes_per_elem, n_kv_groups\\n):\\n    # For GQA, n_kv_heads = n_heads / n_kv_groups\\n    # => scale the MHA total by 1 / n_kv_groups\\n    base = calc_kv_bytes_total_mha(batch, context_length, emb_dim, n_layers, bytes_per_elem)\\n    return base / n_kv_groups\\n\\n\\ndef calc_kv_bytes_total_mha_swa(\\n    batch, context_length, emb_dim, n_layers, bytes_per_elem, window, swa_ratio\\n):\\n    # Split layers into SWA vs Full\\n    a, b = parse_ratio(swa_ratio)\\n    total_blocks = a + b\\n    n_swa_layers = int(round(n_layers * (a / total_blocks)))\\n    n_full_layers = n_layers - n_swa_layers\\n\\n    total_full = calc_kv_bytes_total_mha(\\n        batch, context_length, emb_dim, n_full_layers, bytes_per_elem\\n    )\\n    total_swa = calc_kv_bytes_total_mha(\\n        batch, window, emb_dim, n_swa_layers, bytes_per_elem\\n    )\\n    return total_full + total_swa\\n\\n\\ndef calc_kv_bytes_total_gqa_swa(\\n    batch,\\n    context_length,\\n    emb_dim,\\n    n_layers,\\n    bytes_per_elem,\\n    n_kv_groups,\\n    window,\\n    swa_ratio,\\n):\\n    a, b = parse_ratio(swa_ratio)\\n    total_blocks = a + b\\n    n_swa_layers = int(round(n_layers * (a / total_blocks)))\\n    n_full_layers = n_layers - n_swa_layers\\n\\n    total_full = calc_kv_bytes_total_gqa(\\n        batch,\\n        context_length,\\n        emb_dim,\\n        n_full_layers,\\n        bytes_per_elem,\\n        n_kv_groups,\\n    )\\n    total_swa = calc_kv_bytes_total_gqa(\\n        batch, window, emb_dim, n_swa_layers, bytes_per_elem, n_kv_groups\\n    )\\n    return total_full + total_swa\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"KV-cache vs Context Length \u2014 MHA vs GQA with SWA overlays\\\"\\n    )\\n    p.add_argument(\\\"--emb_dim\\\", type=int, required=True)\\n    p.add_argument(\\\"--n_heads\\\", type=int, required=True)\\n    p.add_argument(\\\"--n_layers\\\", type=int, required=True)\\n    p.add_argument(\\\"--batch_size\\\", type=int, default=1)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"bf16\\\")\\n    p.add_argument(\\n        \\\"--sliding_window_size\\\", type=int, required=True, help=\\\"SWA window size W\\\"\\n    )\\n    p.add_argument(\\\"--swa_ratio\\\", type=str, default=\\\"5:1\\\", help=\\\"SWA:Full ratio, e.g., 5:1\\\")\\n    p.add_argument(\\n        \\\"--output\\\", type=Path, default=Path(\\\"kv_bytes_vs_context_length.pdf\\\")\\n    )\\n    args = p.parse_args()\\n\\n    batch_size = args.batch_size\\n    emb_dim = args.emb_dim\\n    n_heads = args.n_heads\\n    n_layers = args.n_layers\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n\\n    kv_groups = 4\\n    valid_g4 = (n_heads % kv_groups == 0)\\n\\n    context_lengths = [\\n        256, 512, 1024, 2048, 4096, 8192,\\n        16384, 32768, 65536, 131072\\n    ]\\n\\n    series = {\\n        \\\"MHA (KV total)\\\": [],\\n        f\\\"SWA on MHA (ratio {args.swa_ratio}, W={args.sliding_window_size})\\\": [],\\n    }\\n    if valid_g4:\\n        series[\\\"GQA kv_groups=4 (full)\\\"] = []\\n        series[\\n            f\\\"SWA on GQA kv_groups=4 (ratio {args.swa_ratio}, W={args.sliding_window_size})\\\"\\n        ] = []\\n\\n    for L in context_lengths:\\n        total_mha = calc_kv_bytes_total_mha(\\n            batch_size, L, emb_dim, n_layers, bytes_per_elem\\n        )\\n        total_mha_swa = calc_kv_bytes_total_mha_swa(\\n            batch_size,\\n            L,\\n            emb_dim,\\n            n_layers,\\n            bytes_per_elem,\\n            window=args.sliding_window_size,\\n            swa_ratio=args.swa_ratio,\\n        )\\n        series[\\\"MHA (KV total)\\\"].append(convert_bytes_to_gb(total_mha))\\n        series[\\n            f\\\"SWA on MHA (ratio {args.swa_ratio}, W={args.sliding_window_size})\\\"\\n        ].append(convert_bytes_to_gb(total_mha_swa))\\n\\n        if valid_g4:\\n            total_gqa = calc_kv_bytes_total_gqa(\\n                batch_size, L, emb_dim, n_layers, bytes_per_elem, n_kv_groups=kv_groups\\n            )\\n            total_gqa_swa = calc_kv_bytes_total_gqa_swa(\\n                batch_size,\\n                L,\\n                emb_dim,\\n                n_layers,\\n                bytes_per_elem,\\n                n_kv_groups=kv_groups,\\n                window=args.sliding_window_size,\\n                swa_ratio=args.swa_ratio,\\n            )\\n            series[\\\"GQA kv_groups=4 (full)\\\"].append(convert_bytes_to_gb(total_gqa))\\n            series[\\n                f\\\"SWA on GQA kv_groups=4 (ratio {args.swa_ratio}, W={args.sliding_window_size})\\\"\\n            ].append(convert_bytes_to_gb(total_gqa_swa))\\n\\n    plt.figure(figsize=(10, 5))\\n    x = np.array(context_lengths, dtype=float)\\n\\n    colors = {\\n        \\\"MHA\\\": \\\"#1f77b4\\\",\\n        \\\"GQA\\\": \\\"#ff7f0e\\\",\\n    }\\n\\n    for label, yvals in series.items():\\n        y = np.array(yvals, dtype=float)\\n        if np.all(np.isnan(y)):\\n            continue\\n\\n        linestyle = \\\"--\\\" if \\\"SWA\\\" in label else \\\"-\\\"\\n        if \\\"MHA\\\" in label:\\n            color = colors[\\\"MHA\\\"]\\n        elif \\\"GQA\\\" in label:\\n            color = colors[\\\"GQA\\\"]\\n        else:\\n            color = None\\n\\n        plt.plot(x, y, marker=\\\"o\\\", label=label, linestyle=linestyle, color=color)\\n\\n    plt.xscale(\\\"log\\\")\\n    plt.xlabel(\\\"context_length (log scale)\\\")\\n    plt.ylabel(\\\"Total KV cache (GB)\\\")\\n    plt.title(\\n        \\\"KV-cache vs Context Length \u2014 MHA vs GQA (SWA overlays)\\\\n\\\"\\n        f\\\"(n_heads={n_heads}, emb_dim={emb_dim}, n_layers={n_layers}, \\\"\\n        f\\\"batch={batch_size}, dtype={args.dtype}; \\\"\\n        f\\\"SWA ratio={args.swa_ratio}, W={args.sliding_window_size})\\\",\\n        fontsize=8,\\n    )\\n    plt.grid(True, which=\\\"both\\\")\\n    plt.legend()\\n    plt.tight_layout()\\n    plt.savefig(args.output)\\n    plt.close()\\n\\n    if not valid_g4:\\n        print(\\n            f\\\"Skipped GQA kv_groups=4 because n_heads={args.n_heads} \\\"\\n            \\\"is not divisible by 4.\\\"\\n        )\\n    print(f\\\"Saved plot to: {args.output}\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/06_swa/tests.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c0c64ff38cbd7900e3012a79dffe85a1650b59196ad19b38e50df269e5fa0854\",\"content\":\"import copy\\n\\nimport torch\\n\\nfrom llms_from_scratch.ch04 import GPTModel as GPTModelBase\\nfrom llms_from_scratch.ch04 import generate_text_simple\\nfrom gpt_with_kv_swa import GPTModel as GPTModelSWA\\nfrom gpt_with_kv_swa import MultiHeadAttentionWithSWA\\nfrom gpt_with_kv_swa import generate_text_simple_cached\\n\\n\\ndef test_cached_prefill_matches_uncached_swa():\\n    torch.manual_seed(123)\\n\\n    att = MultiHeadAttentionWithSWA(\\n        d_in=8,\\n        d_out=8,\\n        dropout=0.0,\\n        num_heads=2,\\n        sliding_window_size=4,\\n    )\\n    att.eval()\\n    ref_att = copy.deepcopy(att)\\n\\n    x = torch.randn(1, 6, 8)\\n\\n    expected = ref_att(x, use_cache=False)\\n    att.reset_cache()\\n    actual = att(x, use_cache=True)\\n\\n    assert not torch.isnan(actual).any()\\n    assert torch.allclose(actual, expected, atol=1e-6, rtol=0)\\n    assert att.cache_k.size(1) == 4\\n    assert att.cache_v.size(1) == 4\\n\\n\\ndef test_swa_matches_base_model_when_window_equals_context():\\n    cfg = {\\n        \\\"vocab_size\\\": 257,\\n        \\\"context_length\\\": 8,\\n        \\\"emb_dim\\\": 32,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"drop_rate\\\": 0.0,\\n        \\\"qkv_bias\\\": False,\\n    }\\n    swa_cfg = {\\n        **cfg,\\n        \\\"sliding_window_size\\\": cfg[\\\"context_length\\\"],\\n        \\\"sliding_window_stride\\\": -1,\\n    }\\n\\n    torch.manual_seed(123)\\n    base_model = GPTModelBase(cfg)\\n    swa_model = GPTModelSWA(swa_cfg)\\n    base_state = {\\n        key: value\\n        for key, value in base_model.state_dict().items()\\n        if not key.endswith(\\\".att.mask\\\")\\n    }\\n    load_result = swa_model.load_state_dict(base_state, strict=True)\\n    assert not load_result.missing_keys\\n    assert not load_result.unexpected_keys\\n\\n    base_model.eval()\\n    swa_model.eval()\\n\\n    full_input = torch.randint(0, cfg[\\\"vocab_size\\\"], (1, cfg[\\\"context_length\\\"]))\\n    expected_logits = base_model(full_input)\\n    actual_logits = swa_model(full_input, use_cache=False)\\n    torch.testing.assert_close(actual_logits, expected_logits, rtol=0, atol=1e-6)\\n\\n    prompt = full_input[:, :6]\\n    expected_ids = generate_text_simple(\\n        model=base_model,\\n        idx=prompt.clone(),\\n        max_new_tokens=2,\\n        context_size=cfg[\\\"context_length\\\"],\\n    )\\n    actual_ids = generate_text_simple_cached(\\n        model=swa_model,\\n        idx=prompt.clone(),\\n        max_new_tokens=2,\\n        context_size=cfg[\\\"context_length\\\"],\\n        use_cache=True,\\n    )\\n    assert torch.equal(actual_ids, expected_ids)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/07_moe/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7f90f091838d0d3526f221124994c1703d821b039f2cc9fdaea97bbd3e33f798\",\"content\":\"# Mixture of Experts (MoE)\\n\\nThis bonus material illustrates the memory savings (per token) when using Mixture-of-Experts (MoE) layers instead of regular feed-forward (FFN) layers.\\n\\n\\n\\n&nbsp;\\n## Introduction\\n\\nThe core idea in MoE is to replace each feed-forward module in a transformer block with multiple expert layers, where each of these expert layers is also a feed-forward module. This means we replace a single feed-forward block with multiple feed-forward blocks, as illustrated in the figure below.\\n\\n\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/moe-memory/1.webp\\\" alt=\\\"SWA\\\" width=\\\"800px\\\" />\\n\\nThe feed-forward block inside a transformer block (shown as the dark gray block in the figure above) typically contains a large number of the model's total parameters. (Note that the transformer block, and thereby the feed-forward block, is repeated many times in an LLM; in the case of DeepSeek-V3, 61 times.)\\n\\nSo, replacing *a single* feed-forward block with *multiple* feed-forward blocks (as done in a MoE setup) substantially increases the model's total parameter count. However, the key trick is that we don't use (\\\"activate\\\") all experts for every token. Instead, a router selects only a small subset of experts per token.\\n\\nBecause only a few experts are active at a time, MoE modules are often referred to as *sparse*, in contrast to *dense* modules that always use the full parameter set. However, the large total number of parameters via an MoE increases the capacity of the LLM, which means it can take up more knowledge during training. The sparsity keeps inference efficient, though, as we don't use all the parameters at the same time.\\n\\nFor example, DeepSeek-V3 has 256 experts per MoE module and a total of 671 billion parameters. Yet during inference, only 9 experts are active at a time (1 shared expert plus 8 selected by the router). This means just 37 billion parameters are used for each token inference step as opposed to all 671 billion.\\n\\nOne notable feature of DeepSeek-V3's MoE design is the use of a shared expert. This is an expert that is always active for every token. This idea is not new and was already introduced in the [2022 DeepSpeed-MoE](https://arxiv.org/abs/2201.05596) and the [2024 DeepSeek MoE](https://arxiv.org/abs/2401.06066) papers.\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/moe-memory/3.webp?1\\\" alt=\\\"MoE shared expert\\\" width=\\\"500px\\\" />\\n\\n(An annotated figure from the [DeepSeekMoE: Towards Ultimate Expert Specialization in Mixture-of-Experts Language Models](https://arxiv.org/abs/2401.06066) paper.)\\n\\n&nbsp;\\n\\nThe benefit of having a shared expert was first noted in the [DeepSpeed-MoE paper](https://arxiv.org/abs/2201.05596), where they found that it boosts overall modeling performance compared to no shared experts. This is likely because common or repeated patterns don't have to be learned by multiple individual experts, which leaves them with more room for learning more specialized patterns.\\n\\n&nbsp;\\n## Mixture of Experts (MoE) Memory Savings\\n\\nThe memory savings in MoE models primarily come from reduced activation storage and compute. In a regular (dense) feed-forward layer (FFN), every token activates the full intermediate dimension. \\n\\nIn contrast, an MoE layer routes each token through only a small subset of experts (for example, `top_k` out of `num_experts`) per token.\\n\\nWhen using an MoE layer, only `top_k` experts are active per token, so the effective memory (and compute) scales by roughly a factor of `top_k / num_experts` relative to a dense FFN of the same total capacity.\\n\\n\\nYou can use the [memory_estimator_moe.py](memory_estimator_moe.py) script in this folder to apply this for different model configs to see how much memory you can save by using MoE over FFN (note that this is for a single transformer block, to get the total savings, multiply by the number of transformer blocks in your model):\\n\\n```bash\\nuv run memory_estimator_moe.py --emb_dim 7168 --hidden_dim 14336 --ffn_type swiglu \\\\\\n  --num_experts 8 --top_k 2 --match_dense \\n==== Config ====\\nemb_dim                : 7168\\nhidden_size            : 14336\\nffn_type               : swiglu\\nnum_experts            : 8\\ntop_k                  : 2\\ndtype                  : bf16 (2 Bytes/elem)\\nmatch_dense            : True\\n\\n==== Model weights (parameters) ====\\nDense FFN params       : 308,281,344 (0.62 GB)\\nPer-expert params      : 38,535,168 (0.08 GB)\\nRouter params          : 57,344 (0.00 GB)\\nMoE TOTAL params       : 308,338,688 (0.62 GB)\\nMoE ACTIVE/Token       : 77,127,680 (0.15 GB)\\nmoe_hidden_size        : 1792\\n```\\n\\nSo, based on the results above, we can see that if we have a FFN with an input/output dimension (`emb_dim`) of 7,168 and an intermediate size (`hidden_dim`) of 14,336, we have ~308M parameters in this layer, and all these parameters are active in the forward pass.\\n\\nNow, if we use an MoE layer with roughly the same number of total parameters (~308M), with 8 experts where 2 experts are active, only ~77M parameters are active in each forward pass. \\n\\nMoreover, at a constant number of experts, the more experts we have, the lower the number of active parameters becomes, and the greater the \\\"savings\\\":\\n\\n&nbsp;\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/moe-memory/2.webp\\\" alt=\\\"SWA\\\" width=\\\"500px\\\" />\\n\\n\\n\\n&nbsp;\\n\\nYou can reproduce this plot via:\\n\\n```bash\\nuv run plot_memory_estimates_moe.py \\\\\\n    --emb_dim 7168 \\\\\\n    --hidden_dim 28672 \\\\\\n    --ffn_type swiglu \\\\\\n    --top_k 8\\n```\\n\\n\\n&nbsp;\\n## MoE Code Examples\\n\\nThe [gpt_with_kv_ffn.py](gpt_with_kv_ffn.py) and [gpt_with_kv_moe.py](gpt_with_kv_moe.py) scripts in this folder provide hands-on examples for comparing the regular FFN and MoE memory usage in the context of a GPT model implementation. Note that both scripts use [SwiGLU](https://arxiv.org/abs/2002.05202) feed-forward modules as shown in the first figure of this page (GPT-2 traditionally uses GELU).\\n\\n**Note: The model is not trained and thus generates nonsensical text. You can find a trained MoE in the bonus materials at [../../ch05/11_qwen3/standalone-qwen3-moe-plus-kvcache.ipynb](../../ch05/11_qwen3/standalone-qwen3-moe-plus-kvcache.ipynb).**\\n\\n\\n\\nFirst, let's run the model with a regular FFN:\\n\\n\\n```bash\\nuv run gpt_with_kv_ffn.py \\\\\\n--max_new_tokens 1024 \\\\\\n--n_heads 16 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 4096 \\\\\\n--hidden_dim 32768\\n\\n...\\nAvg FFN time/call: 0.759 ms\\nAvg FFN mem delta/call: 0.19 MB (max 0.75 MB)\\n...\\nTime: 25.13 sec\\n40 tokens/sec\\nMax memory allocated: 11.47 GB\\n```\\n\\nFor a fair comparison with an MoE, we have to shrink the expert size. E.g., of we use 32 experts, we have to set `--hidden_dim 32768/32`:\\n\\n\\n```bash\\nuv run gpt_with_kv_moe.py \\\\\\n--max_new_tokens 1024 \\\\\\n--n_heads 16 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 4096 \\\\\\n--hidden_dim 1024 \\\\\\n--num_experts 32 \\\\\\n--num_experts_per_tok 2\\n\\n...\\nAvg MoE FF time/call: 1.555 ms\\nAvg MoE FF mem delta/call: 0.04 MB (max 0.11 MB)\\n...\\nTime: 35.11 sec\\n29 tokens/sec\\nMax memory allocated: 11.48 GB\\n```\\n\\nWe can see that the dense feed-forward layer processes a token in about 0.76 ms and uses roughly 0.19 MB of activations (peaking near 0.75 MB),\\n\\nThe sparse MoE layer keeps only about 0.04 MB of memory (peaking at 0.11). However, this comes at the cost of roughly twice the compute time. (There is an added routing overhead, and my implementation may also not be the most efficient one.)\\n\\nOverall generation still peaks around 11.5 GB of GPU memory in both cases, since both versions load the same number of weight parameters and have the same KV cache size, which dominate here.\\n\\nEither way, we can see the trade-off here where MoE reduces the FFN memory by about 4-5\u00d7 while roughly doubling the feed-forward compute time.\\n\\nNote that if we processed more tokens at one, e.g., with a batch size larger than 1 (here we don't have batches due to code simplicity), the savings would be more pronounced.\\n\\n\\n\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/07_moe/gpt_with_kv_ffn.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8a2f2ac10396cadb023325b94d9f123a3f2ecaef1eadf7087aaa8599db707908\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\nFFN_TIME_MS = []\\nFFN_MEM_BYTES = []\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n            keys, values = self.cache_k, self.cache_v\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\n# class FeedForward(nn.Module):\\n#     def __init__(self, cfg):\\n#         super().__init__()\\n#         self.layers = nn.Sequential(\\n#             nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n#             GELU(),\\n#             nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n#         )\\n\\n#     def forward(self, x):\\n#         return self.layers(x)\\n\\n# Uses SwiGLU instead of GeLU to make it more comparable to MoE\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.fc1 = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"hidden_dim\\\"], bias=False)\\n        self.fc2 = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"hidden_dim\\\"], bias=False)\\n        self.fc3 = nn.Linear(cfg[\\\"hidden_dim\\\"], cfg[\\\"emb_dim\\\"], bias=False)\\n\\n    def forward(self, x):\\n        return self.fc3(torch.nn.functional.silu(self.fc1(x)) * self.fc2(x))\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"],\\n        )\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        use_cuda = torch.cuda.is_available()\\n        if use_cuda:\\n            torch.cuda.synchronize()\\n            torch.cuda.reset_peak_memory_stats()\\n            base_mem = torch.cuda.memory_allocated()\\n        start = time.perf_counter()\\n        x = self.ff(x)\\n        if use_cuda:\\n            torch.cuda.synchronize()\\n            peak_mem = torch.cuda.max_memory_allocated()\\n            FFN_MEM_BYTES.append(peak_mem - base_mem)\\n        FFN_TIME_MS.append((time.perf_counter() - start) * 1000.0)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n    batch_size, base_len = idx.shape\\n    total_len = base_len + max_new_tokens\\n    generated = torch.empty(\\n        batch_size, total_len, dtype=idx.dtype, device=idx.device\\n    )\\n    generated[:, :base_len] = idx\\n    cur_len = base_len\\n    use_cuda = torch.cuda.is_available()\\n    FFN_TIME_MS.clear()\\n    FFN_MEM_BYTES.clear()\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            prompt_start = max(0, cur_len - ctx_len)\\n            logits = model(generated[:, prompt_start:cur_len], use_cache=True)\\n\\n            if use_cuda:\\n                torch.cuda.synchronize()\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1)\\n                # b) append it to the running sequence (in-place)\\n                generated[:, cur_len] = next_idx\\n                cur_len += 1\\n                # c) feed model only the new token\\n                logits = model(generated[:, cur_len - 1 : cur_len], use_cache=True)\\n\\n                if use_cuda:\\n                    torch.cuda.synchronize()\\n        else:\\n            if use_cuda:\\n                torch.cuda.synchronize()\\n\\n            for _ in range(max_new_tokens):\\n                start_ctx = max(0, cur_len - ctx_len)\\n                logits = model(generated[:, start_ctx:cur_len], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1)\\n                generated[:, cur_len] = next_idx\\n                cur_len += 1\\n\\n                if use_cuda:\\n                    torch.cuda.synchronize()\\n\\n    if FFN_TIME_MS:\\n        avg_ffn_time = sum(FFN_TIME_MS) / len(FFN_TIME_MS)\\n        print(f\\\"Avg FFN time/call: {avg_ffn_time:.3f} ms\\\")\\n    if FFN_MEM_BYTES:\\n        avg_ffn_mem = sum(FFN_MEM_BYTES) / len(FFN_MEM_BYTES)\\n        max_ffn_mem = max(FFN_MEM_BYTES)\\n\\n        def to_mb(bytes_val):\\n            return bytes_val / (1024 ** 2)\\n        print(f\\\"Avg FFN mem delta/call: {to_mb(avg_ffn_mem):.2f} MB (max {to_mb(max_ffn_mem):.2f} MB)\\\")\\n\\n    return generated[:, :cur_len]\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter)\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--hidden_dim\\\", type=int, default=768*4, help=\\\"Intermediate FFN size.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n    parser.add_argument(\\n        \\\"--no_kv_cache\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Disable KV caching during generation.\\\",\\n    )\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,            # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,        # Embedding dimension\\n        \\\"hidden_dim\\\": args.hidden_dim,  # Intermediate size\\n        \\\"n_heads\\\": args.n_heads,        # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,      # Number of layers\\n        \\\"drop_rate\\\": 0.0,               # Dropout rate\\n        \\\"qkv_bias\\\": False,              # Query-Key-Value bias\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n        use_cache=not args.no_kv_cache,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/07_moe/gpt_with_kv_moe.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3087f942bce1edbe64b5f61a6e5d83aef9c5340b1d1bd209aa643a91fc156195\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\nMOE_FF_TIME_MS = []\\nMOE_FF_MEM_BYTES = []\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n            keys, values = self.cache_k, self.cache_v\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"hidden_dim\\\"]),\\n            GELU(),\\n            nn.Linear(cfg[\\\"hidden_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass MoEFeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.num_experts_per_tok = cfg[\\\"num_experts_per_tok\\\"]\\n        self.num_experts = cfg[\\\"num_experts\\\"]\\n        self.emb_dim = cfg[\\\"emb_dim\\\"]\\n\\n        self.gate = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"num_experts\\\"], bias=False)\\n        self.fc1 = nn.ModuleList(\\n            [\\n                nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"hidden_dim\\\"], bias=False)\\n                for _ in range(self.num_experts)\\n            ]\\n        )\\n        self.fc2 = nn.ModuleList(\\n            [\\n                nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"hidden_dim\\\"], bias=False)\\n                for _ in range(self.num_experts)\\n            ]\\n        )\\n        self.fc3 = nn.ModuleList(\\n            [\\n                nn.Linear(cfg[\\\"hidden_dim\\\"], cfg[\\\"emb_dim\\\"], bias=False)\\n                for _ in range(self.num_experts)\\n            ]\\n        )\\n\\n    def forward(self, x):\\n        # x: (batch, seq_len, emb_dim)\\n        scores = self.gate(x)  # (b, seq_len, num_experts)\\n        topk_scores, topk_indices = torch.topk(scores, self.num_experts_per_tok, dim=-1)\\n        topk_probs = torch.softmax(topk_scores, dim=-1)\\n\\n        batch, seq_len, _ = x.shape\\n        x_flat = x.reshape(batch * seq_len, -1)\\n        out_flat = torch.zeros(batch * seq_len, self.emb_dim, device=x.device, dtype=x.dtype)\\n\\n        topk_indices_flat = topk_indices.reshape(-1, self.num_experts_per_tok)\\n        topk_probs_flat = topk_probs.reshape(-1, self.num_experts_per_tok)\\n\\n        unique_experts = torch.unique(topk_indices_flat)\\n\\n        for expert_id_tensor in unique_experts:\\n            expert_id = int(expert_id_tensor.item())\\n\\n            mask = topk_indices_flat == expert_id\\n            if not mask.any():\\n                continue\\n\\n            token_mask = mask.any(dim=-1)\\n            selected_idx = token_mask.nonzero(as_tuple=False).squeeze(-1)\\n            if selected_idx.numel() == 0:\\n                continue\\n\\n            expert_input = x_flat.index_select(0, selected_idx)\\n            hidden = torch.nn.functional.silu(self.fc1[expert_id](expert_input)) * self.fc2[\\n                expert_id\\n            ](expert_input)\\n            expert_out = self.fc3[expert_id](hidden)\\n\\n            mask_selected = mask[selected_idx]\\n            slot_indices = mask_selected.int().argmax(dim=-1, keepdim=True)\\n            selected_probs = torch.gather(\\n                topk_probs_flat.index_select(0, selected_idx), dim=-1, index=slot_indices\\n            ).squeeze(-1)\\n\\n            out_flat.index_add_(0, selected_idx, expert_out * selected_probs.unsqueeze(-1))\\n\\n        return out_flat.reshape(batch, seq_len, self.emb_dim)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"],\\n        )\\n        self.ff = MoEFeedForward(cfg) if cfg[\\\"num_experts\\\"] > 0 else FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        use_cuda = torch.cuda.is_available()\\n        if use_cuda:\\n            torch.cuda.synchronize()\\n            torch.cuda.reset_peak_memory_stats()\\n            base_mem = torch.cuda.memory_allocated()\\n        start = time.perf_counter()\\n        x = self.ff(x)\\n        if use_cuda:\\n            torch.cuda.synchronize()\\n            peak_mem = torch.cuda.max_memory_allocated()\\n            MOE_FF_MEM_BYTES.append(peak_mem - base_mem)\\n        MOE_FF_TIME_MS.append((time.perf_counter() - start) * 1000.0)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n    batch_size, base_len = idx.shape\\n    total_len = base_len + max_new_tokens\\n    generated = torch.empty(\\n        batch_size, total_len, dtype=idx.dtype, device=idx.device\\n    )\\n    generated[:, :base_len] = idx\\n    cur_len = base_len\\n    use_cuda = torch.cuda.is_available()\\n    MOE_FF_TIME_MS.clear()\\n    MOE_FF_MEM_BYTES.clear()\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            prompt_start = max(0, cur_len - ctx_len)\\n            logits = model(generated[:, prompt_start:cur_len], use_cache=True)\\n\\n            if use_cuda:\\n                torch.cuda.synchronize()\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1)\\n                # b) append it to the running sequence (in-place)\\n                generated[:, cur_len] = next_idx\\n                cur_len += 1\\n                # c) feed model only the new token\\n                logits = model(generated[:, cur_len - 1 : cur_len], use_cache=True)\\n\\n                if use_cuda:\\n                    torch.cuda.synchronize()\\n        else:\\n            if use_cuda:\\n                torch.cuda.synchronize()\\n\\n            for _ in range(max_new_tokens):\\n                start_ctx = max(0, cur_len - ctx_len)\\n                logits = model(generated[:, start_ctx:cur_len], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1)\\n                generated[:, cur_len] = next_idx\\n                cur_len += 1\\n\\n                if use_cuda:\\n                    torch.cuda.synchronize()\\n\\n    if MOE_FF_TIME_MS:\\n        avg_ffn_time = sum(MOE_FF_TIME_MS) / len(MOE_FF_TIME_MS)\\n        print(f\\\"Avg MoE FF time/call: {avg_ffn_time:.3f} ms\\\")\\n    if MOE_FF_MEM_BYTES:\\n        avg_ffn_mem = sum(MOE_FF_MEM_BYTES) / len(MOE_FF_MEM_BYTES)\\n        max_ffn_mem = max(MOE_FF_MEM_BYTES)\\n\\n        def to_mb(bytes_val):\\n            return bytes_val / (1024 ** 2)\\n        print(f\\\"Avg MoE FF mem delta/call: {to_mb(avg_ffn_mem):.2f} MB (max {to_mb(max_ffn_mem):.2f} MB)\\\")\\n\\n    return generated[:, :cur_len]\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter)\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--hidden_dim\\\", type=int, default=768*4, help=\\\"Intermediate FFN or MoE size.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n    parser.add_argument(\\n        \\\"--no_kv_cache\\\",\\n        action=\\\"store_true\\\",\\n        help=\\\"Disable KV caching during generation.\\\",\\n    )\\n\\n    parser.add_argument(\\n        \\\"--num_experts\\\",\\n        type=int,\\n        default=0,\\n        help=\\\"Number of experts. If 0, use dense FFN. If >0, use MoE.\\\",\\n    )\\n    parser.add_argument(\\n        \\\"--num_experts_per_tok\\\",\\n        type=int,\\n        default=2,\\n        help=\\\"Top-k experts per token when using MoE (ignored if num_experts=0).\\\",\\n    )\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,            # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,        # Embedding dimension\\n        \\\"hidden_dim\\\": args.hidden_dim,  # Intermediate size\\n        \\\"n_heads\\\": args.n_heads,        # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,      # Number of layers\\n        \\\"drop_rate\\\": 0.0,               # Dropout rate\\n        \\\"qkv_bias\\\": False,              # Query-Key-Value bias\\n        \\\"num_experts\\\": args.num_experts,\\n        \\\"num_experts_per_tok\\\": args.num_experts_per_tok if args.num_experts > 0 else 0,\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n        use_cache=not args.no_kv_cache,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/07_moe/memory_estimator_moe.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a23bd82274d04084c5bc000fa0b64eaf455986092985fa777d7e6edab7ad6d8\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport argparse\\n\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes(n):\\n    gb = n / (1000 ** 3)\\n    return f\\\"{gb:,.2f} GB\\\"\\n\\n\\ndef get_num_param_matrices(ffn_type):\\n    if ffn_type == \\\"gelu\\\":\\n        return 2\\n    elif ffn_type == \\\"swiglu\\\":\\n        return 3\\n    else:\\n        raise ValueError(\\\"--ffn_type must be 'gelu' or 'swiglu'\\\")\\n\\n\\ndef calc_ffn_params(emb_dim, hidden_dim, ffn_type):\\n    return get_num_param_matrices(ffn_type) * emb_dim * hidden_dim\\n\\n\\ndef calc_router_params(emb_dim, num_experts):\\n    return emb_dim * num_experts\\n\\n\\ndef estimate_params_and_hidden(\\n    emb_dim, hidden_dim, ffn_type, num_experts, match_dense=False\\n):\\n    P_dense = calc_ffn_params(emb_dim, hidden_dim, ffn_type)\\n    R = calc_router_params(emb_dim, num_experts)\\n\\n    if match_dense:\\n        num_param_matrices = get_num_param_matrices(ffn_type)\\n        num = P_dense - R\\n        den = num_experts * num_param_matrices * emb_dim\\n        if num <= 0:\\n            raise ValueError(\\\"Dense layer too small for requested num_experts.\\\")\\n        moe_hidden_dim = int(round(num / float(den)))\\n    else:\\n        moe_hidden_dim = hidden_dim\\n\\n    per_expert_params = calc_ffn_params(emb_dim, moe_hidden_dim, ffn_type)\\n    moe_total = num_experts * per_expert_params + R\\n\\n    return {\\n        \\\"dense_params\\\": P_dense,\\n        \\\"router\\\": R,\\n        \\\"moe_hidden_dim\\\": moe_hidden_dim,\\n        \\\"per_expert_params\\\": per_expert_params,\\n        \\\"moe_total\\\": moe_total,\\n    }\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"Estimate FFN vs MoE parameter memory\\\"\\n    )\\n    p.add_argument(\\\"--emb_dim\\\", type=int, required=True,\\n                   help=\\\"Model embedding dimension.\\\")\\n    p.add_argument(\\\"--hidden_dim\\\", type=int, required=True,\\n                   help=\\\"Dense FFN intermediate size (hidden dimension).\\\")\\n    p.add_argument(\\\"--ffn_type\\\", choices=[\\\"gelu\\\", \\\"swiglu\\\"], default=\\\"swiglu\\\")\\n    p.add_argument(\\\"--num_experts\\\", type=int, default=8)\\n    p.add_argument(\\\"--top_k\\\", type=int, default=2)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"bf16\\\")\\n    p.add_argument(\\n        \\\"--match_dense\\\",\\n        action=\\\"store_true\\\",\\n        help=(\\\"Auto-set per-expert hidden so MoE total params ~= dense FFN params \\\"\\n              \\\"(router included).\\\"),\\n    )\\n    args = p.parse_args()\\n\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n\\n    res = estimate_params_and_hidden(\\n        emb_dim=args.emb_dim,\\n        hidden_dim=args.hidden_dim,\\n        ffn_type=args.ffn_type,\\n        num_experts=args.num_experts,\\n        match_dense=args.match_dense,\\n    )\\n\\n    moe_active_params_per_token = (\\n        res[\\\"router\\\"] + args.top_k * res[\\\"per_expert_params\\\"]\\n    )\\n\\n    print(\\\"==== Config ====\\\")\\n    print(f\\\"{'emb_dim':23}: {args.emb_dim}\\\")\\n    print(f\\\"{'hidden_dim':23}: {args.hidden_dim}\\\")\\n    print(f\\\"{'ffn_type':23}: {args.ffn_type}\\\")\\n    print(f\\\"{'num_experts':23}: {args.num_experts}\\\")\\n    print(f\\\"{'top_k':23}: {args.top_k}\\\")\\n    print(f\\\"{'dtype':23}: {args.dtype} ({bytes_per_elem} Bytes/elem)\\\")\\n    print(f\\\"{'match_dense':23}: {args.match_dense}\\\")\\n    print()\\n\\n    print(\\\"==== Model weights (parameters) ====\\\")\\n    print(f\\\"{'Dense FFN params':23}: {res['dense_params']:,} \\\"\\n          f\\\"({convert_bytes(res['dense_params'] * bytes_per_elem)})\\\")\\n    print(f\\\"{'Per-expert params':23}: {res['per_expert_params']:,} \\\"\\n          f\\\"({convert_bytes(res['per_expert_params'] * bytes_per_elem)})\\\")\\n    print(f\\\"{'Router params':23}: {res['router']:,} \\\"\\n          f\\\"({convert_bytes(res['router'] * bytes_per_elem)})\\\")\\n    print(f\\\"{'MoE TOTAL params':23}: {res['moe_total']:,} \\\"\\n          f\\\"({convert_bytes(res['moe_total'] * bytes_per_elem)})\\\")\\n    print(f\\\"{'MoE ACTIVE/Token':23}: {moe_active_params_per_token:,} \\\"\\n          f\\\"({convert_bytes(moe_active_params_per_token * bytes_per_elem)})\\\")\\n    print(f\\\"{'moe_hidden_dim':23}: {res['moe_hidden_dim']}\\\")\\n    print()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/07_moe/plot_memory_estimates_moe.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"64a5667997dab57090540b01b671e882b53807a90ccf41f6dca009ae80949349\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\nimport argparse\\nimport matplotlib.pyplot as plt\\nfrom memory_estimator_moe import (\\n    estimate_params_and_hidden,\\n    calc_ffn_params,\\n    calc_router_params,\\n)\\n\\n\\ndef calc_moe_active_and_total(\\n    emb_dim,\\n    hidden_dim,\\n    ffn_type,\\n    num_experts,\\n    top_k,\\n    match_dense=True,\\n):\\n    if match_dense:\\n        dense_params = calc_ffn_params(emb_dim, hidden_dim, ffn_type)\\n        router = calc_router_params(emb_dim, num_experts)\\n        if dense_params <= router:\\n            match_dense = False\\n\\n    stats = estimate_params_and_hidden(\\n        emb_dim=emb_dim,\\n        hidden_dim=hidden_dim,\\n        ffn_type=ffn_type,\\n        num_experts=num_experts,\\n        match_dense=match_dense,\\n    )\\n\\n    active = stats[\\\"router\\\"] + top_k * stats[\\\"per_expert_params\\\"]\\n    return active, stats[\\\"moe_total\\\"]\\n\\n\\ndef plot_active_params_vs_experts(\\n    emb_dim,\\n    hidden_dim,\\n    ffn_type=\\\"swiglu\\\",\\n    top_k=2,\\n    max_experts=512,\\n    y_log=True,\\n    save_path=None,\\n    match_dense=True,\\n):\\n    experts = [1, 2, 4, 8, 16, 32, 64, 128, 192, 256, 384, 512]\\n    experts = [e for e in experts if e <= max_experts]\\n\\n    dense_active = calc_ffn_params(emb_dim, hidden_dim, ffn_type)\\n    moe_active = []\\n    moe_total = []\\n    for e in experts:\\n        active, total = calc_moe_active_and_total(\\n            emb_dim=emb_dim,\\n            hidden_dim=hidden_dim,\\n            ffn_type=ffn_type,\\n            num_experts=e,\\n            top_k=top_k,\\n            match_dense=match_dense,\\n        )\\n        moe_active.append(active)\\n        moe_total.append(total)\\n\\n    plt.figure(figsize=(7, 5))\\n    plt.plot(experts, moe_active, marker=\\\"o\\\", label=\\\"MoE active per token\\\")\\n    plt.plot(experts, moe_total, marker=\\\"s\\\", linestyle=\\\"--\\\", label=\\\"MoE total parameters\\\")\\n    plt.axhline(dense_active, linestyle=\\\":\\\", color=\\\"gray\\\",\\n                label=\\\"FFN dense (active = total)\\\")\\n\\n    plt.xlabel(f\\\"Number of experts (top_k = {top_k})\\\")\\n    plt.ylabel(\\\"Parameters\\\")\\n    if y_log:\\n        plt.yscale(\\\"log\\\")\\n    plt.title(\\n        f\\\"Active vs Total Parameters per Token\\\\n\\\"\\n        f\\\"(emb_dim={emb_dim}, hidden_dim={hidden_dim}, ffn={ffn_type}, top_k={top_k})\\\"\\n    )\\n    plt.legend()\\n    plt.tight_layout()\\n    if save_path:\\n        plt.savefig(save_path, dpi=200)\\n        print(f\\\"Saved plot to {save_path}\\\")\\n    else:\\n        plt.show()\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Plot Dense vs MoE active parameters.\\\")\\n    p.add_argument(\\\"--emb_dim\\\", type=int, required=True, help=\\\"Embedding dimension\\\")\\n    p.add_argument(\\\"--hidden_dim\\\", type=int, required=True, help=\\\"Dense FFN hidden size\\\")\\n    p.add_argument(\\\"--ffn_type\\\", choices=[\\\"gelu\\\", \\\"swiglu\\\"], default=\\\"swiglu\\\")\\n    p.add_argument(\\\"--top_k\\\", type=int, default=2, help=\\\"Active experts per token\\\")\\n    p.add_argument(\\\"--max_experts\\\", type=int, default=512, help=\\\"Max experts on x-axis\\\")\\n    p.add_argument(\\\"--no_log\\\", action=\\\"store_true\\\", help=\\\"Disable log-scale y-axis\\\")\\n    p.add_argument(\\\"--save\\\", type=str, default=None, help=\\\"Optional path to save PNG\\\")\\n    p.add_argument(\\n        \\\"--no_match_dense\\\",\\n        action=\\\"store_true\\\",\\n        help=(\\\"Disable matching MoE parameters to dense FFN total; \\\"\\n              \\\"uses provided hidden_dim instead.\\\"),\\n    )\\n    args = p.parse_args()\\n\\n    plot_active_params_vs_experts(\\n        emb_dim=args.emb_dim,\\n        hidden_dim=args.hidden_dim,\\n        ffn_type=args.ffn_type,\\n        top_k=args.top_k,\\n        max_experts=args.max_experts,\\n        y_log=not args.no_log,\\n        save_path=args.save,\\n        match_dense=not args.no_match_dense,\\n    )\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/08_deltanet/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a152d6be1406798b7f44abbbdf07fd50a3c47287df337410f1cb8514658fc381\",\"content\":\"# Gated DeltaNet for Linear Attention\\n\\nRecently, [Qwen3-Next](https://qwen.ai/blog?id=4074cca80393150c248e508aa62983f9cb7d27cd&from=research.latest-advancements-list) and [Kimi Linear](https://arxiv.org/abs/2510.26692) proposed hybrid transformers that implement alternatives to the attention mechanism that scale linearly instead of quadratically with respect to the context length.\\n\\nBoth Qwen3-Next and Kimi Linear use a 3:1 ratio, meaning for every three transformer blocks employing the linear Gated DeltaNet variant, there\u2019s one block that uses full attention, as shown in the figure below.\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gated_deltanet/01.webp\\\" alt=\\\"Qwen3-Next versus Kimi Linear\\\">\\n\\n\\n\\n&nbsp;\\n\\n## Introduction and Overview\\n\\nGated DeltaNet is a linear attention variant with inspiration from recurrent neural networks, including a gating mechanism from the [Gated Delta Networks: Improving Mamba2 with Delta Rule](https://arxiv.org/abs/2412.06464) paper. In a sense, Gated DeltaNet is a DeltaNet with Mamba-style gating, and DeltaNet is a linear attention mechanism.\\n\\nKimi Linear modifies the linear attention mechanism of Qwen3-Next by the Kimi Delta Attention (KDA) mechanism, which is essentially a refinement of Gated DeltaNet. Whereas Qwen3-Next applies a scalar gate (one value per attention head) to control the memory decay rate, Kimi Linear replaces it with a channel-wise gating for each feature dimension. According to the authors, this gives more control over the memory, and this, in turn, improves long-context reasoning.\\n\\nIn addition, for the full attention layers, Kimi Linear replaces Qwen3-Next\u2019s gated attention layers (which are essentially standard multi-head attention layers with output gating) with Multi-Head Latent Attention (MLA). This is the same MLA mechanism we discussed earlier in the DeepSeek V3/R1 section, but with an additional gate. (To recap, MLA compresses the key/value space to reduce the KV cache size.)\\n\\nThe MLA in Kimi Linear does not use the gate, which was intentional so that the authors could compare the architecture more directly to standard MLA, however, they [stated](https://x.com/yzhang_cs/status/1984631714464088563) that they plan to add it in the future.\\n\\nSince we already implemented MLA in [../05_mla](../05_mla), this bonus material focuses on the Gated DeltaNet aspect.\\n\\n\\n&nbsp;\\n## Gated Attention\\n\\nBefore we get to the Gated DeltaNet itself, let's briefly talk about the gate. As you can see in the upper part of the Qwen3-Next architecture in the previous figure, Qwen3-Next uses \\\"gated attention\\\". This is essentially regular full attention with an additional sigmoid gate.\\n\\nThis gating is a simple modification that I added to the `MultiHeadAttention`  code from chapter 3 below for illustration purposes:\\n\\n```python\\nimport torch\\nfrom torch import nn\\n\\nclass GatedMultiHeadAttention(nn.Module):\\n    def __init__(\\n        self, d_in, d_out, context_length, dropout, num_heads, qkv_bias=False\\n    ):\\n        super().__init__()\\n        assert d_out % num_heads == 0\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        ####################################################\\n        ### NEW: Add gate\\n        self.W_gate = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        ####################################################\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n\\n        self.out_proj = nn.Linear(d_out, d_out)\\n        self.dropout = nn.Dropout(dropout)\\n\\n        self.register_buffer(\\n            \\\"mask\\\",\\n            torch.triu(torch.ones(context_length, context_length), diagonal=1),\\n            persistent=False,\\n        )\\n\\n    def forward(self, x):\\n        b, num_tokens, _ = x.shape\\n        queries = self.W_query(x)\\n        ####################################################\\n        ### NEW: Add gate\\n        gate = self.W_gate(x)\\n        ####################################################\\n        keys = self.W_key(x)\\n        values = self.W_value(x)\\n\\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        attn_scores = queries @ keys.transpose(2, 3)\\n\\n        mask_bool = self.mask.bool()[:num_tokens, :num_tokens]\\n        attn_scores.masked_fill_(\\n            mask_bool, torch.finfo(attn_scores.dtype).min\\n        )\\n\\n        attn_weights = torch.softmax(\\n            attn_scores / (self.head_dim ** 0.5), dim=-1\\n        )\\n        attn_weights = self.dropout(attn_weights)\\n\\n        context = (attn_weights @ values).transpose(1, 2)\\n        context = context.reshape(b, num_tokens, self.d_out)\\n\\n        ####################################################\\n        ### NEW: Add gate\\n        context = context * torch.sigmoid(gate)\\n        ####################################################\\n        out = self.out_proj(context)\\n        return out\\n```\\n\\n\\n\\nAs we can see, after computing attention as usual, the model uses a separate gating signal from the same input, applies a sigmoid to keep it between 0 and 1, and multiplies it with the attention output. This allows the model to scale up or down certain features dynamically. The Qwen3-Next developers [state](https://qwen.ai/blog?id=4074cca80393150c248e508aa62983f9cb7d27cd&from=research.latest-advancements-list) that this helps with training stability:\\n\\n> [...] the attention output gating mechanism helps eliminate issues like Attention Sink and Massive Activation, ensuring numerical stability across the model.\\n\\n\\n&nbsp;\\n## Gated DeltaNet\\n\\nNow, what is Gated DeltaNet? Gated DeltaNet (short for *Gated Delta Network*) is Qwen3-Next's linear-attention layer, which is intended as an alternative to standard softmax attention. It was adopted from the [Gated Delta Networks: Improving Mamba2 with Delta Rule](https://arxiv.org/abs/2412.06464) paper as mentioned earlier.\\n\\nGated DeltaNet was originally proposed as an improved version of Mamba2, where it combines the gated decay mechanism of Mamba2 with a delta rule.\\n\\nMamba is a state-space model (an alternative to transformers), a big topic that deserves separate coverage in the future.\\n\\nThe delta rule part refers to computing the difference (delta, \u0394) between new and predicted values to update a hidden state that is used as a memory state (more on that later).\\n\\n(Side note: Readers with classic machine learning literature can think of this as similar to Hebbian learning inspired by biology: \\\"Cells that fire together wire together.\\\" It's basically a precursor of the perceptron update rule and gradient descent-based learning, but without supervision.)\\n\\nGated DeltaNet has a gate similar to the gate in gated attention discussed earlier, except that it uses a SiLU instead of logistic sigmoid activation, as illustrated below. (The SiLU choice is likely to improve gradient flow and stability over the standard sigmoid.)\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gated_deltanet/02.webp\\\" alt=\\\"Gated DeltaNet\\\" width=500px>\\n\\nHowever, as shown in the figure above, the \\\"gated\\\" in the Gated DeltaNet also refers to several additional gates:\\n\\n- `\u03b1` (decay gate) controls how fast the memory decays or resets over time,\\n- `\u03b2` (update gate) controls how strongly new inputs modify the state.\\n\\nIn code, a simplified version of the Gated DeltaNet depicted above (without the convolutional mixing) can be implemented as follows (the code is inspired by the [official implementation](https://github.com/huggingface/transformers/blob/0ed6d51ae8ed3f4fafca67a983b8d75bc76cd51b/src/transformers/models/qwen3_next/modular_qwen3_next.py#L835) by the Qwen3 team).\\n\\n(Note that some implementations refer to the decay gate as `gk` (gate for step k), where `exp(gk)` matches the paper's $\\\\alpha_t$. To keep this relationship explicit, the snippet below separates the log-space gate `alpha_log` from the exponentiated decay `alpha`.)\\n\\n\\n```python\\nimport torch\\nfrom torch import nn\\nimport torch.nn.functional as F\\n\\ndef l2norm(x, dim=-1, eps=1e-6):\\n    return x * torch.rsqrt((x * x).sum(dim=dim, keepdim=True) + eps)\\n\\nclass GatedDeltaNet(nn.Module):\\n    def __init__(\\n        self, d_in, d_out, dropout, num_heads, qkv_bias=False\\n    ):\\n        super().__init__()\\n        assert d_out % num_heads == 0\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        ####################################################\\n        ### NEW: Gates for delta rule and output gating\\n        self.W_gate = nn.Linear(d_in, d_out, bias=False)\\n        self.W_beta = nn.Linear(d_in, d_out, bias=False)\\n\\n        # Note: The decay gate alpha corresponds to\\n        # A_log + W_alpha(x) + dt_bias\\n        self.W_alpha = nn.Linear(d_in, num_heads, bias=False)\\n        self.dt_bias = nn.Parameter(torch.ones(num_heads))\\n        A_init = torch.empty(num_heads).uniform_(0, 16)\\n        self.A_log = nn.Parameter(torch.log(A_init))\\n        # We could implement this as\\n        # W_alpha = nn.Linear(d_in, num_heads, bias=True)\\n        # but the bias is separate for interpretability and\\n        # to mimic the official implementation\\n\\n        self.norm = nn.RMSNorm(self.head_dim, eps=1e-6)\\n        ####################################################\\n\\n        self.out_proj = nn.Linear(d_out, d_out)\\n        self.dropout = nn.Dropout(dropout)\\n\\n    def forward(self, x):\\n        b, num_tokens, _ = x.shape\\n        queries = self.W_query(x)\\n        keys = self.W_key(x)\\n        values = self.W_value(x)\\n        ####################################################\\n        ### NEW: Compute delta rule gates\\n        beta = torch.sigmoid(self.W_beta(x))\\n        alpha_log = -self.A_log.exp().view(1, 1, -1) * F.softplus(\\n            self.W_alpha(x) + self.dt_bias\\n        )\\n        alpha = alpha_log.exp()\\n        gate = self.W_gate(x)\\n        ####################################################\\n\\n        keys = keys.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values = values.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n        beta = beta.view(b, num_tokens, self.num_heads, self.head_dim)\\n        gate = gate.view(b, num_tokens, self.num_heads, self.head_dim)  # NEW\\n\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n        beta = beta.transpose(1, 2)\\n\\n        ####################################################\\n        ### NEW: QKNorm-like normalization for delta rule\\n        queries = l2norm(queries, dim=-1) / (self.head_dim ** 0.5)\\n        keys = l2norm(keys, dim=-1)\\n        ####################################################\\n\\n        S = x.new_zeros(b, self.num_heads, self.head_dim, self.head_dim)\\n\\n        outs = []\\n        ####################################################\\n        ### NEW: Gated delta rule update\\n        for t in range(num_tokens):\\n            k_t = keys[:, :, t]\\n            q_t = queries[:, :, t]\\n            v_t = values[:, :, t]\\n            b_t = beta[:, :, t]\\n            a_t = alpha[:, t].unsqueeze(-1).unsqueeze(-1)\\n\\n            S = S * a_t\\n            kv_mem = (S * k_t.unsqueeze(-1)).sum(dim=-2)\\n            delta = (v_t - kv_mem) * b_t\\n            S = S + k_t.unsqueeze(-1) * delta.unsqueeze(-2)\\n            y_t = (S * q_t.unsqueeze(-1)).sum(dim=-2)\\n            ####################################################\\n            outs.append(y_t)\\n\\n        context = torch.stack(outs, dim=2).transpose(1, 2).contiguous()\\n        context = context.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        ### NEW: Apply RMSNorm and SiLU gate\\n        context = self.norm(context)\\n        context = context * F.silu(gate)\\n        ####################################################\\n\\n        context = context.view(b, num_tokens, self.d_out)\\n        context = self.dropout(context)\\n        out = self.out_proj(context)\\n        return out\\n```\\n\\n(Note that for simplicity, I omitted the convolutional mixing that Qwen3-Next and Kimi Linear use to keep the code more readable and focus on the recurrent aspects.)\\n\\nSo, as we can see above, there are lots of differences to standard (or gated) attention.\\n\\nIn gated attention, the model computes normal attention between all tokens (every token attends or looks at every other token). Then, after getting the attention output, a gate (a sigmoid) decides how much of that output to keep. The takeaway is that it's still the the regular scaled-dot product attention that scales quadratically with the context length.\\n\\nAs a refresher, scaled-dot production attention is computed as softmax(QK\u1d40)V, where Q and K are *n*-by-*d* matrices, where *n* is the number of input tokens, and *d* is the embedding dimension. So QK\u1d40 results in an attention *n*-by-*n* matrix, that is multiplied by a *n*-by-*d* dimensional value matrix V:\\n\\n```\\nattn_scores = queries @ keys.transpose(2, 3)\\n\\nmask_bool = self.mask.bool()[:num_tokens, :num_tokens]\\nattn_scores.masked_fill_(\\n    mask_bool, torch.finfo(attn_scores.dtype).min\\n)\\n\\nattn_weights = torch.softmax(\\n    attn_scores / (self.head_dim ** 0.5), dim=-1\\n)\\n\\ncontext = (attn_weights @ values).transpose(1, 2)\\ncontext = context.reshape(b, num_tokens, self.d_out)\\n```\\n\\n\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gated_deltanet/03.webp\\\" alt=\\\"Quadratic attention\\\" width=500px />\\n\\nIn Gated DeltaNet, there's no  *n*-by-*n* attention matrix. Instead, the model processes tokens one by one. It keeps a running memory (a state) that gets updated as each new token comes in. This is what's implemented as, where `S` is the state that gets updated recurrently for each time step *t*.\\n\\n```python\\nS = x.new_zeros(b, self.num_heads, self.head_dim, self.head_dim)\\nouts = []\\n\\nfor t in range(num_tokens):\\n    k_t = keys[:, :, t]\\n    q_t = queries[:, :, t]\\n    v_t = values[:, :, t]\\n    b_t = beta[:, :, t]\\n    a_t = alpha[:, t].unsqueeze(-1).unsqueeze(-1)\\n\\n    S = S * a_t\\n    kv_mem = (S * k_t.unsqueeze(-1)).sum(dim=-2)\\n    delta = (v_t - kv_mem) * b_t\\n    S = S + k_t.unsqueeze(-1) * delta.unsqueeze(-2)\\n    y_t = (S * q_t.unsqueeze(-1)).sum(dim=-2)\\n```\\n\\nAnd the gates control how that memory changes:\\n\\n- \u03b1 (`alpha`) regulates how much of the old memory to forget (decay).\\n\\n- \u03b2 (`beta`) regulates how much the current token at time step *t* updates the memory.\\n\\n(And the final output gate, not shown in the snippet above, is similar to gated attention; it controls how much of the output is kept.)\\n\\nSo, in a sense, this state update in Gated DeltaNet is similar to how recurrent neural networks (RNNs) work. The advantage is that it scales linearly (via the for-loop) instead of quadratically with context length.\\n\\nThe downside of this recurrent state update is that, compared to regular (or gated) attention, it sacrifices the global context modeling ability that comes from full pairwise attention.\\n\\nGated DeltaNet, can, to some extend, still capture context, but it has to go through the memory (*S*) bottleneck. That memory is a fixed size and thus more efficient, but it compresses past context into a single hidden state similar to RNNs.\\n\\nThat's why the Qwen3-Next and Kimi Linear architectures don't replace all attention layers with DeltaNet layers but use the 3:1 ratio mentioned earlier.\\n\\n&nbsp;\\n## DeltaNet Memory Savings\\n\\nIn the previous section, we discussed the advantage of the DeltaNet over full attention in terms of linear instead of quadratic compute complexity with respect to the context length.\\n\\nNext to the linear compute complexity, another big advantage of DeltaNet is the memory savings, as DeltaNet modules don't grow the KV cache. (For more information about KV caching, see [../03_kv-cache](../03_kv-cache)). Instead, as mentioned earlier, they keep a fixed-size recurrent state, so memory stays constant with context length.\\n\\nFor a regular multi-head attention (MHA) layer, we can compute the KV cache size as follows:\\n\\n```\\nKV_cache_MHA \u2248 batch_size \u00d7 n_tokens \u00d7 n_heads \u00d7 d_head \u00d7 2 \u00d7 bytes\\n```\\n\\n(The 2 multiplier is there because we have both keys and values that we store in the cache.)\\n\\nFor the simplified DeltaNet version implemented above, we have:\\n\\n\\n```\\nKV_cache_DeltaNet = batch_size \u00d7 n_heads \u00d7 d_head \u00d7 d_head \u00d7 bytes\\n```\\n\\nNote that the `KV_cache_DeltaNet` memory size doesn't have a context length (`n_tokens`) dependency. Also, we have only the memory state S that we store instead of separate keys and values, hence `2 \u00d7 bytes` becomes just `bytes`. However, note that we now have a quadratic `d_head \u00d7 d_head` in here. This comes from the state :\\n\\n```\\nS = x.new_zeros(b, self.num_heads, self.head_dim, self.head_dim)\\n```\\n\\nBut that's usually nothing to worry about, as the head dimension is usually relatively small. For instance, it's 128 in Qwen3-Next.\\n\\nThe full version with the convolutional mixing is a bit more complex, including the kernel size and so on, but the formulas above should illustrate the main trend and motivation behind the Gated DeltaNet.\\n\\nWe can visualize the memory estimates and savings for different context lengths via the following helper script:\\n\\n```bash\\nuv run plot_memory_estimates_gated_deltanet.py \\\\\\n  --emb_dim 2048 \\\\\\n  --n_heads 16 \\\\\\n  --n_layers 48 \\\\\\n  --dtype \\\"bf16\\\"\\n```\\n\\nNote that the above computes the `head_dim` as `emb_dim / n_heads`. I.e., 2048 / 16  = 128.\\n\\n<img src=\\\"https://sebastianraschka.com/images/LLMs-from-scratch-images/bonus/gated_deltanet/plot.webp\\\" alt=\\\"Gated DeltaNet scaling\\\" width=500px>\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/08_deltanet/plot_memory_estimates_gated_deltanet.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"02ce7efb62e60754a30fd65927da8bc74620af1415bcbeda471d81d2c07f1007\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\nimport argparse\\nimport numpy as np\\nimport matplotlib.pyplot as plt\\n\\n# Bytes per element\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef calc_kv_bytes_total_mha(batch, context_length, emb_dim, n_layers, bytes_per_elem, n_heads):\\n    # Full attention (MHA)\\n    d_head = emb_dim // n_heads\\n    per_layer = batch * context_length * n_heads * d_head * 2 * bytes_per_elem\\n    return per_layer * n_layers\\n\\n\\ndef calc_kv_bytes_total_deltanet_no_conv(batch, emb_dim, n_layers, bytes_per_elem, n_heads):\\n    # Simple Gated DeltaNet (no convolutional mixing)\\n    d_head = emb_dim // n_heads\\n    per_layer = batch * n_heads * d_head * d_head * bytes_per_elem\\n    return per_layer * n_layers\\n\\n\\ndef convert_to_gb(x):\\n    return x / 1e9\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(formatter_class=argparse.ArgumentDefaultsHelpFormatter, description=\\\"Memory vs. Context Length: MHA vs. DeltaNet (3:1 mix)\\\")\\n    p.add_argument(\\\"--batch\\\", type=int, default=1)\\n    p.add_argument(\\\"--emb_dim\\\", type=int, default=2048)\\n    p.add_argument(\\\"--n_heads\\\", type=int, default=16)\\n    p.add_argument(\\\"--n_layers\\\", type=int, default=48)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"bf16\\\")\\n    p.add_argument(\\\"--min_ctx\\\", type=int, default=128)\\n    p.add_argument(\\\"--max_ctx\\\", type=int, default=131_072)\\n    args = p.parse_args()\\n\\n    step = 100\\n    ctx = np.arange(args.min_ctx, args.max_ctx + 1, step, dtype=int)\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n\\n    # 1) Full attention only\\n    mha_bytes = np.array([\\n        calc_kv_bytes_total_mha(args.batch, int(t), args.emb_dim, args.n_layers,\\n                                     bytes_per_elem, args.n_heads)\\n        for t in ctx\\n    ], dtype=float)\\n\\n    # 2) DeltaNet only\\n    dnet_bytes_const = calc_kv_bytes_total_deltanet_no_conv(\\n        args.batch, args.emb_dim, args.n_layers,\\n        bytes_per_elem, args.n_heads\\n    )\\n    dnet_bytes = np.full_like(mha_bytes, fill_value=dnet_bytes_const, dtype=float)\\n\\n    # 3) 3:1 layer ratio (3 DeltaNet : 1 Full Attention)\\n    n_mha_layers = args.n_layers / 4\\n    n_dnet_layers = args.n_layers - n_mha_layers\\n    mix_bytes = np.array([\\n        calc_kv_bytes_total_mha(args.batch, int(t), args.emb_dim, n_mha_layers,\\n                                     bytes_per_elem, args.n_heads)\\n        + calc_kv_bytes_total_deltanet_no_conv(args.batch, args.emb_dim, n_dnet_layers,\\n                                                    bytes_per_elem, args.n_heads)\\n        for t in ctx\\n    ], dtype=float)\\n\\n    # Convert to GB\\n    mha_gb = convert_to_gb(mha_bytes)\\n    dnet_gb = convert_to_gb(dnet_bytes)\\n    mix_gb = convert_to_gb(mix_bytes)\\n\\n    # Plot\\n    fig, ax = plt.subplots(figsize=(7, 4.5))\\n    ax.plot(ctx, mha_gb, label=\\\"Full Attention (MHA) KV cache\\\")\\n    ax.plot(ctx, dnet_gb, label=\\\"All Gated DeltaNet (no conv)\\\")\\n    ax.plot(ctx, mix_gb, label=\\\"3:1 layer ratio (3 DeltaNet : 1 Full Attention)\\\")\\n\\n    ax.set_xlabel(\\\"Context length (number of tokens)\\\")\\n    ax.set_ylabel(\\\"KV cache size (GB)\\\")\\n    ax.grid(True, which=\\\"both\\\", linestyle=\\\"--\\\", linewidth=0.5, alpha=0.6)\\n    ax.legend()\\n\\n    fig.tight_layout()\\n    plt.savefig(\\\"deltanet_memory_plot.pdf\\\", dpi=160)\\n    plt.close(fig)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/09_dsa/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"19fb3886f277be349c6a856a6c75a4d0b0ee0c0f464ea84158a4689f8b75c948\",\"content\":\"# DeepSeek Sparse Attention (DSA)\\n\\nThis bonus material implements the DeepSeek Sparse Attention (DSA) mechanism introduced in [DeepSeek-V3.2](https://huggingface.co/deepseek-ai/DeepSeek-V3.2) and first published in the experimental [DeepSeek-V3.2-Exp](https://huggingface.co/deepseek-ai/DeepSeek-V3.2-Exp) release.\\n\\nThe overview below follows the DSA discussion in [From DeepSeek V3 to V3.2: Architecture, Sparse Attention, and RL Updates](https://magazine.sebastianraschka.com/p/technical-deepseek).\\n\\n&nbsp;\\n## Introduction\\n\\nStandard causal self-attention attends to all previous tokens for each query, yielding O(L\u00b2) compute and O(L) KV-cache growth with sequence length L.\\n\\n[Sliding Window Attention (SWA)](../06_swa) already showed that restricting attention to a fixed local window substantially reduces this cost. In SWA, each query token attends only to a local span of nearby previous tokens.\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/blog/2025/technical-deepseek/09.png\\\" alt=\\\"Sliding window attention\\\" width=\\\"800px\\\" />\\n\\n*Figure 1. Sliding-window attention restricts each query token to a fixed local context window.*\\n\\n&nbsp;\\n\\nDSA uses the same broad idea of attending to only a subset of previous tokens. However, it replaces the fixed window with a learned selection mechanism. For each query token, the model scores candidate past tokens and keeps only the most relevant ones.\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/blog/2025/technical-deepseek/10.png\\\" alt=\\\"DeepSeek Sparse Attention selected-token pattern\\\" width=\\\"800px\\\" />\\n\\n*Figure 2. DeepSeek Sparse Attention selects a learned subset of past tokens for each query token.*\\n\\n&nbsp;\\n\\n### Architecture overview\\n\\nDSA adds two components on top of standard attention.\\n\\n**1. Lightning Indexer**\\n\\nFor each query token $t$ and every candidate past token $s$, the indexer computes a scalar relevance score. This implementation makes the scale factors from the reference code explicit:\\n\\n$$I_{t,s} = \\\\sum_{j=1}^{H_I} \\\\frac{w_{t,j}}{\\\\sqrt{H_I}} \\\\cdot \\\\text{ReLU}\\\\left(\\\\frac{q_{t,j} \\\\cdot k_s}{\\\\sqrt{d_I}}\\\\right)$$\\n\\nwhere:\\n- $H_I$ is the number of lightweight index heads,\\n- $q_{t,j}$ is the indexer query vector for token $t$ and head $j$,\\n- $k_s$ is a shared indexer key vector for past token $s$,\\n- $w_{t,j}$ is a learned per-head gate scaled by $1 / \\\\sqrt{H_I}$.\\n\\nThe ReLU zeroes out negative dot-product contributions, and the gated sum aggregates across index heads into a single relevance score per past token.\\n\\nIn the full DeepSeek model, the indexer works with the compressed token representations from Multi-Head Latent Attention (MLA). This folder keeps the GPT implementation simpler and computes the indexer queries and keys from the regular hidden states.\\n\\n**2. Token Selector**\\n\\nAfter computing all indexer scores, only the top-K highest-scoring positions are kept. All other positions are masked to \u2212\u221e *before* the standard softmax, so the model effectively attends to only $k \\\\ll L$ tokens.\\n\\nThe ReLU in the indexer is not where the final sparsity comes from. Since the scores are summed over multiple index heads, most final scores can still be nonzero. The token selector creates the sparse pattern by keeping only the top-K positions.\\n\\nIn a fused production implementation, this can lower attention compute from O(L\u00b2) to O(L\u00b7k). The implementation here keeps the standard dense attention score matrix and applies the DSA-selected top-K mask before softmax. This makes the selection logic easy to inspect, but it does not provide the fused-kernel compute savings.\\n\\nThe figure below summarizes the flow. The lightning indexer scores candidate tokens, the selector keeps top-K positions, and the resulting mask restricts the usual attention softmax.\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/blog/2025/technical-deepseek/11.png\\\" alt=\\\"DeepSeek Sparse Attention flowchart\\\" width=\\\"700px\\\" />\\n\\n*Figure 3. DSA first scores candidate tokens, then keeps the top-K tokens for the final attention mask.*\\n\\n&nbsp;\\n## Implementation\\n\\n`gpt_with_kv_dsa.py` provides:\\n\\n| Class | Description |\\n|---|---|\\n| `LightningIndexer` | Lightweight multi-head scorer for past-token relevance. |\\n| `MultiHeadAttentionWithDSA` | Standard MHA with DSA sparse masking + optional KV cache. |\\n| `GPTModel` | GPT-style model swapping in `MultiHeadAttentionWithDSA`. |\\n\\nThe implementation follows the style of the other bonus material in this repository and can be run as a standalone script. It is meant to make the DSA mechanism inspectable in a small GPT-style model. It does not implement DeepSeek's full MLA stack, fused sparse kernels, or deployment-specific optimizations.\\n\\n&nbsp;\\n## Usage\\n\\n```bash\\nuv run gpt_with_kv_dsa.py \\\\\\n  --emb_dim 768 \\\\\\n  --n_heads 12 \\\\\\n  --n_layers 12 \\\\\\n  --max_new_tokens 200 \\\\\\n  --index_n_heads 4 \\\\\\n  --index_head_dim 64 \\\\\\n  --topk 64\\n```\\n\\nKey arguments:\\n\\n| Argument | Default | Description |\\n|---|---|---|\\n| `--index_n_heads` | 4 | Number of lightweight indexer heads (H_I). |\\n| `--index_head_dim` | 64 | Dimension of each indexer head. |\\n| `--topk` | 64 | Number of tokens each query attends to (k). Capped at sequence length for short sequences. |\\n\\n&nbsp;\\n## Relation to DeepSeek V3.2\\n\\nThe full-scale DeepSeek-V3.2 model uses Multi-Head Latent Attention (MLA, see [../05_mla](../05_mla)) alongside DSA, and the indexer queries are derived from the shared compressed latent representation rather than the raw input. DeepSeek-V3.2 uses the same architecture as DeepSeek-V3.2-Exp, where DSA was first introduced and tested.\\n\\nThe key selection idea is reproduced here. A cheap learned dot-product scorer limits each query to the most relevant tokens before the attention softmax.\\n\\nThe reported inference-cost comparison below is useful context for why DSA matters in long-context deployments. The savings depend on production kernels and serving infrastructure, so this figure should not be read as a benchmark for the teaching implementation in this folder.\\n\\n&nbsp;\\n\\n<img src=\\\"https://sebastianraschka.com/images/blog/2025/technical-deepseek/19.png\\\" alt=\\\"Inference cost comparison for DeepSeek Sparse Attention\\\" width=\\\"800px\\\" />\\n\\n*Figure 4. DeepSeek's reported inference-cost savings from DSA in long-context serving, from the [DeepSeek V3.2 technical report](https://huggingface.co/deepseek-ai/DeepSeek-V3.2/resolve/main/assets/paper.pdf).*\\n\\n&nbsp;\\n## References\\n\\n- DeepSeek V3.2 technical report: https://huggingface.co/deepseek-ai/DeepSeek-V3.2/resolve/main/assets/paper.pdf\\n- DeepSeek V3.2-Exp model card & reference code: https://huggingface.co/deepseek-ai/DeepSeek-V3.2-Exp\\n- Sebastian Raschka's \\\"From DeepSeek V3 to V3.2: Architecture, Sparse Attention, and RL Updates\\\": https://magazine.sebastianraschka.com/p/technical-deepseek\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/09_dsa/gpt_with_kv_dsa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"2153f12765da847b0bedb3647b62b6ed98dc568e0cecbd7f6909d27a3ea7f822\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4, adapted to use DeepSeek Sparse Attention (DSA).\\n# This file can be run as a standalone script.\\n\\n# DSA is introduced in DeepSeek-V3.2:\\n#   https://huggingface.co/deepseek-ai/DeepSeek-V3.2\\n# Technical report:\\n#   https://huggingface.co/deepseek-ai/DeepSeek-V3.2/resolve/main/assets/paper.pdf\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# DeepSeek Sparse Attention (DSA)\\n#####################################\\n# DSA combines two components:\\n#   1. A Lightning Indexer that scores all past tokens for each query\\n#      using a lightweight gated sum of ReLU(q \u00b7 k) dot products.\\n#   2. A Token Selector that picks the top-K highest-scoring past tokens\\n#      and masks out the rest.\\n#\\n# This teaching implementation applies a dense mask to standard attention.\\n# It reproduces the DSA selection logic but does not include a fused sparse\\n# attention kernel that would reduce attention compute from O(L^2) to O(L*k).\\n#\\n# Reference implementation inspired by:\\n#   https://huggingface.co/deepseek-ai/DeepSeek-V3.2-Exp/blob/main/inference/model.py\\n\\n\\nclass LightningIndexer(nn.Module):\\n    \\\"\\\"\\\"Lightweight module that scores every past token for each incoming query.\\n\\n    For each query token t and each candidate past token s, the score is a\\n    gated sum of per-head dot products:\\n        I_{t,s} = sum_j [ (w_{t,j} / sqrt(H_I)) * ReLU((q_{t,j} \u00b7 k_s) / sqrt(d_I)) ]\\n\\n    where w_{t,j} is a learned per-head scalar weight derived from the input,\\n    H_I is the number of index heads, d_I is the index head dimension, and j\\n    indexes over the index heads.\\n\\n    Args:\\n        d_model:       model dimension (same as emb_dim).\\n        index_n_heads: number of lightweight index heads (H_I in the paper).\\n        index_head_dim: dimension of each index head.\\n    \\\"\\\"\\\"\\n\\n    def __init__(self, d_model: int, index_n_heads: int, index_head_dim: int):\\n        super().__init__()\\n        self.index_n_heads = index_n_heads\\n        self.index_head_dim = index_head_dim\\n\\n        # Project input to indexer query vectors: (d_model -> index_n_heads * index_head_dim)\\n        self.W_q_index = nn.Linear(d_model, index_n_heads * index_head_dim, bias=False)\\n        # Project input to shared key vectors: (d_model -> index_head_dim)\\n        self.W_k_index = nn.Linear(d_model, index_head_dim, bias=False)\\n        # Learn a per-head weight scalar: (d_model -> index_n_heads), as in the V3.2 paper\\n        self.W_weights = nn.Linear(d_model, index_n_heads, bias=False)\\n\\n        self.scale = index_head_dim ** -0.5\\n\\n    def forward(\\n        self,\\n        x: torch.Tensor,         # (b, T, d_model)  current token(s)\\n        x_ctx: torch.Tensor,     # (b, S, d_model)  all past + current tokens\\n        topk: int,\\n        causal_mask: torch.Tensor | None = None,  # (T, S) float mask\\n    ) -> torch.Tensor:\\n        \\\"\\\"\\\"Return top-K token indices shape (b, T, topk).\\\"\\\"\\\"\\n        b, T, _ = x.shape\\n        _, S, _ = x_ctx.shape\\n\\n        # Indexer queries: (b, T, H_I, head_dim)\\n        q = self.W_q_index(x).view(b, T, self.index_n_heads, self.index_head_dim)\\n        # Indexer keys: (b, S, head_dim)\\n        k = self.W_k_index(x_ctx)  # (b, S, head_dim)\\n\\n        # ReLU(q \u00b7 k^T) for each head: (b, T, H_I, S)\\n        # k: (b, S, head_dim) -> (b, 1, S, head_dim) for broadcast\\n        raw = torch.einsum(\\\"bthd,bsd->bths\\\", q, k) * self.scale  # (b, T, H_I, S)\\n        raw = torch.relu(raw)\\n\\n        # Per-head learned gates: (b, T, H_I)\\n        # Reference implementations use raw learned gates scaled by sqrt(H_I),\\n        # not a probability distribution over index heads.\\n        w = self.W_weights(x)  # (b, T, H_I)\\n        w = w * (self.index_n_heads ** -0.5)\\n\\n        # Weighted sum over heads -> index scores (b, T, S)\\n        index_scores = torch.einsum(\\\"bth,bths->bts\\\", w, raw)  # (b, T, S)\\n\\n        if causal_mask is not None:\\n            index_scores = index_scores + causal_mask  # broadcast over batch\\n\\n        # Select top-K positions. topk is capped at available context length S.\\n        k_val = min(topk, S)\\n        topk_indices = index_scores.topk(k_val, dim=-1).indices  # (b, T, k)\\n        return topk_indices\\n\\n\\nclass MultiHeadAttentionWithDSA(nn.Module):\\n    \\\"\\\"\\\"Multi-head causal self-attention with DeepSeek Sparse Attention (DSA).\\n\\n    After computing full attention scores, the Lightning Indexer selects the\\n    top-K most relevant past tokens for each query, and all other positions\\n    are masked to -inf before softmax. This keeps the selected-token behavior\\n    of DSA while using a dense attention matrix for clarity.\\n\\n    Args:\\n        d_in:           input dimension.\\n        d_out:          output dimension (must be divisible by num_heads).\\n        dropout:        dropout probability.\\n        num_heads:      number of standard attention heads.\\n        qkv_bias:       whether to use bias in Q/K/V projections.\\n        index_n_heads:  number of lightweight index heads (H_I).\\n        index_head_dim: dimension per index head.\\n        topk:           number of tokens each query attends to (k).\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        d_in: int,\\n        d_out: int,\\n        dropout: float,\\n        num_heads: int,\\n        qkv_bias: bool = False,\\n        index_n_heads: int = 4,\\n        index_head_dim: int = 64,\\n        topk: int = 64,\\n    ):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads\\n        self.topk = topk\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)\\n        self.dropout = nn.Dropout(dropout)\\n\\n        self.indexer = LightningIndexer(d_in, index_n_heads, index_head_dim)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        # Keep raw input tokens for the indexer key projection\\n        self.register_buffer(\\\"cache_x\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def reset_cache(self):\\n        self.cache_k = None\\n        self.cache_v = None\\n        self.cache_x = None\\n        self.ptr_current_pos = 0\\n\\n    def forward(self, x: torch.Tensor, use_cache: bool = False) -> torch.Tensor:\\n        b, num_tokens, d_in = x.shape\\n\\n        queries = self.W_query(x)\\n        keys_new = self.W_key(x)\\n        values_new = self.W_value(x)\\n\\n        # Reshape to (b, T, num_heads, head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                keys = keys_new\\n                values = values_new\\n                x_ctx = x\\n            else:\\n                keys = torch.cat([self.cache_k, keys_new], dim=1)\\n                values = torch.cat([self.cache_v, values_new], dim=1)\\n                x_ctx = torch.cat([self.cache_x, x], dim=1)\\n            self.cache_k = keys\\n            self.cache_v = values\\n            self.cache_x = x_ctx\\n            q_start = self.ptr_current_pos\\n            k_start = 0\\n            self.ptr_current_pos += num_tokens\\n        else:\\n            keys = keys_new\\n            values = values_new\\n            x_ctx = x\\n            q_start = 0\\n            k_start = 0\\n        ####################################################\\n\\n        # Transpose: (b, T, num_heads, head_dim) -> (b, num_heads, T, head_dim)\\n        queries_t = queries.transpose(1, 2)\\n        keys_t = keys.transpose(1, 2)\\n        values_t = values.transpose(1, 2)\\n\\n        # Full scaled dot-product attention scores: (b, num_heads, T_q, T_k)\\n        attn_scores = queries_t @ keys_t.transpose(2, 3)\\n\\n        num_tokens_Q = queries_t.shape[-2]\\n        num_tokens_K = keys_t.shape[-2]\\n        device = x.device\\n\\n        # ---- Build causal mask (float, -inf for masked positions) ----\\n        q_positions = torch.arange(q_start, q_start + num_tokens_Q, device=device, dtype=torch.long)\\n        k_positions = torch.arange(k_start, k_start + num_tokens_K, device=device, dtype=torch.long)\\n        causal_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)  # (T_q, T_k)\\n        causal_float = torch.zeros(num_tokens_Q, num_tokens_K, device=device, dtype=attn_scores.dtype)\\n        causal_float.masked_fill_(causal_bool, float(\\\"-inf\\\"))\\n\\n        # ---- DSA: Lightning Indexer \u2192 sparse mask ----\\n        # The indexer receives the current queries (x) and all context tokens (x_ctx).\\n        # causal_float is passed so future tokens are excluded from index selection.\\n        topk_indices = self.indexer(x, x_ctx, self.topk, causal_mask=causal_float)\\n        # topk_indices: (b, T_q, k)\\n\\n        # Build sparse mask: -inf everywhere, 0 at selected positions\\n        sparse_mask = torch.full(\\n            (b, num_tokens_Q, num_tokens_K), float(\\\"-inf\\\"), device=device, dtype=attn_scores.dtype\\n        )\\n        sparse_mask.scatter_(-1, topk_indices, 0.0)  # (b, T_q, T_k)\\n\\n        # Combine causal mask and sparse mask, then broadcast over heads\\n        combined_mask = causal_float.unsqueeze(0) + sparse_mask  # (b, T_q, T_k)\\n        attn_scores = attn_scores + combined_mask.unsqueeze(1)  # (b, num_heads, T_q, T_k)\\n\\n        attn_weights = torch.softmax(attn_scores / self.head_dim ** 0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_heads, T_q, head_dim)\\n        context_vec = attn_weights @ values_t\\n        # Transpose and reshape: (b, T_q, d_out)\\n        context_vec = context_vec.transpose(1, 2).contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)\\n        return context_vec\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttentionWithDSA(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"],\\n            index_n_heads=cfg[\\\"index_n_heads\\\"],\\n            index_head_dim=cfg[\\\"index_head_dim\\\"],\\n            topk=cfg[\\\"topk\\\"],\\n        )\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        ####################################################\\n        # KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        ####################################################\\n        # KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(\\n        formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"Run GPT with DeepSeek Sparse Attention (DSA).\\\"\\n    )\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n    parser.add_argument(\\\"--index_n_heads\\\", type=int, default=4,\\n                        help=\\\"Number of lightweight indexer heads (H_I in the DSA paper).\\\")\\n    parser.add_argument(\\\"--index_head_dim\\\", type=int, default=64,\\n                        help=\\\"Dimension of each indexer head.\\\")\\n    parser.add_argument(\\\"--topk\\\", type=int, default=64,\\n                        help=\\\"Number of tokens each query attends to (k). \\\"\\n                             \\\"For short sequences this is capped at sequence length.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n        \\\"index_n_heads\\\": args.index_n_heads,\\n        \\\"index_head_dim\\\": args.index_head_dim,\\n        \\\"topk\\\": args.topk,\\n    }\\n\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/09_dsa/test_dsa.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5382204f3421a42f7977d3f9388beb22ea60bbeb678b0ff15334d05243dcca8d\",\"content\":\"import os\\n\\nimport pytest\\nimport torch\\nimport torch.nn as nn\\nimport tiktoken\\n\\nfrom gpt_with_kv_dsa import (\\n    GPTModel,\\n    LightningIndexer,\\n    MultiHeadAttentionWithDSA,\\n    generate_text_simple_cached,\\n)\\n\\n\\ndef import_transformers_dsa_model():\\n    \\\"\\\"\\\"Import the reference DSA model from the installed Transformers package.\\\"\\\"\\\"\\n    try:\\n        from transformers import GlmMoeDsaConfig, GlmMoeDsaModel\\n    except ImportError as err:\\n        pytest.skip(f\\\"Transformers GLM-MoE-DSA reference unavailable: {err}\\\")\\n\\n    return GlmMoeDsaConfig, GlmMoeDsaModel\\n\\n\\ndef test_output_shape():\\n    \\\"\\\"\\\"Output shape must be (batch, seq_len, d_out).\\\"\\\"\\\"\\n    torch.manual_seed(0)\\n    b, T, d = 2, 20, 128\\n    attn = MultiHeadAttentionWithDSA(\\n        d_in=d, d_out=d, dropout=0.0, num_heads=4,\\n        index_n_heads=2, index_head_dim=16, topk=5,\\n    )\\n    x = torch.randn(b, T, d)\\n    out = attn(x)\\n    assert out.shape == (b, T, d), f\\\"Wrong shape: {out.shape}\\\"\\n\\n\\ndef test_causal_property():\\n    \\\"\\\"\\\"Tokens at position p must not be affected by tokens at positions > p.\\\"\\\"\\\"\\n    torch.manual_seed(1)\\n    b, T, d = 1, 20, 128\\n    attn = MultiHeadAttentionWithDSA(\\n        d_in=d, d_out=d, dropout=0.0, num_heads=4,\\n        index_n_heads=2, index_head_dim=16, topk=5,\\n    )\\n    x = torch.randn(b, T, d)\\n    out_full = attn(x)\\n\\n    # Replace tokens at positions 6+ with random noise\\n    x_noisy = x.clone()\\n    x_noisy[:, 6:, :] = torch.randn(b, T - 6, d)\\n    out_noisy = attn(x_noisy)\\n\\n    torch.testing.assert_close(out_noisy[:, :6, :], out_full[:, :6, :], rtol=0, atol=1e-5)\\n\\n\\ndef test_sparsity():\\n    \\\"\\\"\\\"Each query must attend to at most topk tokens.\\\"\\\"\\\"\\n    torch.manual_seed(2)\\n    b, T, d = 1, 20, 128\\n    topk = 5\\n    attn = MultiHeadAttentionWithDSA(\\n        d_in=d, d_out=d, dropout=0.0, num_heads=4,\\n        index_n_heads=2, index_head_dim=16, topk=topk,\\n    )\\n    x = torch.randn(b, T, d)\\n\\n    # Reconstruct the combined (causal + sparse) mask\\n    q_pos = torch.arange(T)\\n    k_pos = torch.arange(T)\\n    causal_bool = q_pos.unsqueeze(-1) < k_pos.unsqueeze(0)\\n    causal_float = torch.zeros(T, T).masked_fill_(causal_bool, float(\\\"-inf\\\"))\\n\\n    topk_idx = attn.indexer(x, x, topk)\\n    sparse_mask = torch.full((b, T, T), float(\\\"-inf\\\"))\\n    sparse_mask.scatter_(-1, topk_idx, 0.0)\\n\\n    combined = causal_float.unsqueeze(0) + sparse_mask   # (1, T, T)\\n    counts = (combined[0] > float(\\\"-inf\\\")).sum(dim=-1).float()\\n\\n    assert int(counts.max()) <= topk\\n\\n\\n@pytest.mark.skipif(\\n    os.environ.get(\\\"GITHUB_ACTIONS\\\") == \\\"true\\\",\\n    reason=\\\"Transformers reference test is too expensive for GitHub Actions\\\",\\n)\\ndef test_indexer_matches_transformers_reference():\\n    \\\"\\\"\\\"The indexer must match the Transformers DSA scoring path.\\\"\\\"\\\"\\n    torch.manual_seed(4)\\n    b, T, d = 2, 6, 32\\n    topk = 3\\n    indexer = LightningIndexer(d_model=d, index_n_heads=4, index_head_dim=8)\\n    GlmMoeDsaConfig, GlmMoeDsaModel = import_transformers_dsa_model()\\n    reference_cfg = GlmMoeDsaConfig(\\n        vocab_size=128,\\n        hidden_size=d,\\n        intermediate_size=64,\\n        moe_intermediate_size=16,\\n        num_hidden_layers=1,\\n        num_attention_heads=4,\\n        num_key_value_heads=4,\\n        kv_lora_rank=8,\\n        index_n_heads=indexer.index_n_heads,\\n        index_head_dim=indexer.index_head_dim,\\n        index_topk=topk,\\n        q_lora_rank=d,\\n        qk_rope_head_dim=0,\\n        qk_nope_head_dim=8,\\n        v_head_dim=8,\\n        n_routed_experts=4,\\n        num_experts_per_tok=1,\\n        max_position_embeddings=16,\\n        mlp_layer_types=[\\\"dense\\\"],\\n    )\\n    reference_model = GlmMoeDsaModel(reference_cfg)\\n    reference_model.eval()\\n    reference = reference_model.layers[0].self_attn.indexer\\n    reference.k_norm = nn.Identity()\\n    with torch.no_grad():\\n        reference.wq_b.weight.copy_(indexer.W_q_index.weight)\\n        reference.wk.weight.copy_(indexer.W_k_index.weight)\\n        reference.weights_proj.weight.copy_(indexer.W_weights.weight)\\n\\n    x = torch.randn(b, T, d)\\n    q_pos = torch.arange(T)\\n    k_pos = torch.arange(T)\\n    causal_bool = q_pos.unsqueeze(-1) < k_pos.unsqueeze(0)\\n    causal_mask = torch.zeros(T, T).masked_fill_(causal_bool, float(\\\"-inf\\\"))\\n\\n    actual = indexer(x, x, topk=topk, causal_mask=causal_mask)\\n    empty_rope = torch.empty(b, T, 0)\\n    expected = reference(x, x, (empty_rope, empty_rope), causal_mask)\\n    assert torch.equal(actual, expected)\\n\\n\\ndef test_cache_consistency():\\n    \\\"\\\"\\\"Cached and non-cached generation must produce identical token sequences.\\\"\\\"\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(\\\"Hello, I am\\\")\\n    cfg = {\\n        \\\"vocab_size\\\": 50257,\\n        \\\"context_length\\\": 30,\\n        \\\"emb_dim\\\": 256,\\n        \\\"n_heads\\\": 4,\\n        \\\"n_layers\\\": 2,\\n        \\\"drop_rate\\\": 0.0,\\n        \\\"qkv_bias\\\": False,\\n        \\\"index_n_heads\\\": 2,\\n        \\\"index_head_dim\\\": 32,\\n        \\\"topk\\\": 200,   # large topk == full attention, so both modes match exactly\\n    }\\n    torch.manual_seed(42)\\n    model = GPTModel(cfg)\\n    model.eval()\\n    idx = torch.tensor(encoded).unsqueeze(0)\\n    out_no_cache = generate_text_simple_cached(model, idx.clone(), max_new_tokens=5, use_cache=False)\\n    out_with_cache = generate_text_simple_cached(model, idx.clone(), max_new_tokens=5, use_cache=True)\\n    assert torch.equal(out_no_cache, out_with_cache)\\n\\n\\ndef dense_attention_reference(attn, x):\\n    \\\"\\\"\\\"Dense causal attention using the same projections as the DSA module.\\\"\\\"\\\"\\n    b, T, _ = x.shape\\n\\n    queries = attn.W_query(x).view(b, T, attn.num_heads, attn.head_dim).transpose(1, 2)\\n    keys = attn.W_key(x).view(b, T, attn.num_heads, attn.head_dim).transpose(1, 2)\\n    values = attn.W_value(x).view(b, T, attn.num_heads, attn.head_dim).transpose(1, 2)\\n\\n    attn_scores = queries @ keys.transpose(2, 3)\\n    mask = torch.triu(torch.ones(T, T, dtype=torch.bool, device=x.device), diagonal=1)\\n    attn_scores = attn_scores.masked_fill(mask, float(\\\"-inf\\\"))\\n\\n    attn_weights = torch.softmax(attn_scores / attn.head_dim ** 0.5, dim=-1)\\n    context_vec = attn_weights @ values\\n    context_vec = context_vec.transpose(1, 2).contiguous().view(b, T, attn.d_out)\\n    return attn.out_proj(context_vec)\\n\\n\\ndef test_topk_full_equals_dense():\\n    \\\"\\\"\\\"With topk >= seq_len the sparse mask is all-zeros -> identical to dense attention.\\\"\\\"\\\"\\n    torch.manual_seed(3)\\n    b, T, d = 1, 10, 64\\n\\n    attn_full = MultiHeadAttentionWithDSA(\\n        d_in=d, d_out=d, dropout=0.0, num_heads=4,\\n        index_n_heads=2, index_head_dim=16, topk=T,\\n    )\\n    x = torch.randn(b, T, d)\\n    out_dsa = attn_full(x)\\n    out_dense = dense_attention_reference(attn_full, x)\\n    torch.testing.assert_close(out_dsa, out_dense, rtol=0, atol=1e-5)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/10_kv-sharing/README.md\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e6750a4810d5b5112dcee8ebb6fc1dad36b76e12233fd2fa0dd20dbdfb22fe05\",\"content\":\"# Cross-Layer KV Sharing\\n\\nThis bonus material illustrates the memory savings when using cross-layer KV sharing together with a KV cache.\\n\\n&nbsp;\\n## Introduction\\n\\nIn [../04_gqa](../04_gqa), we discussed Grouped-Query Attention (GQA), where several query heads share the same key and value heads. Cross-layer KV sharing applies a related idea across transformer layers.\\n\\nInstead of computing a fresh key and value projection in every layer, later layers reuse K/V tensors from an earlier layer. They still compute their own queries, so each layer can form its own attention pattern. The main memory saving comes from storing fewer K/V tensors in the cache.\\n\\nThis idea is also called cross-layer attention. It is described in Brandon *et al.*, [Reducing Transformer Key-Value Cache Size with Cross-Layer Attention](https://arxiv.org/abs/2405.12981). Gemma 4 E2B and E4B use a related shared KV-cache scheme, which makes this a useful addition to the GQA, MLA, and SWA examples in this chapter.\\n\\n&nbsp;\\n\\n<img src=\\\"gemma4-kv-sharing.webp\\\" alt=\\\"Cross-layer KV sharing\\\" width=\\\"800px\\\" />\\n\\n&nbsp;\\n\\nIn [Gemma 4](../../ch05/17_gemma4), KV sharing is combined with GQA or MQA and sliding window attention. For the simplified GPT example in this folder, we only implement the cross-layer KV-sharing part, so the code stays focused on the main mechanism.\\n\\nThe simplified rule used here is:\\n\\n1. Early layers compute and cache their own K/V tensors.\\n2. Later layers reuse the most recent K/V tensors from an earlier producing layer.\\n3. All layers still compute their own query projections.\\n\\nThis reduces the number of K/V caches that grow with context length. The tradeoff is reduced model capacity because some layers no longer get their own K/V projections.\\n\\n&nbsp;\\n## KV-Sharing Memory Savings\\n\\nThe usual KV-cache memory is computed as follows:\\n\\nbytes = batch_size x seqlen x head_dim x n_kv_heads x n_layers x 2 (K,V) x bytes_per_elem\\n\\nWith cross-layer KV sharing, we replace `n_layers` with the number of K/V-producing layers:\\n\\nbytes = batch_size x seqlen x head_dim x n_kv_heads x n_kv_producing_layers x 2 (K,V) x bytes_per_elem\\n\\nYou can use the [memory_estimator_kv_sharing.py](memory_estimator_kv_sharing.py) script in this folder to apply this to different model configs:\\n\\n```bash\\n# Gemma 4 E2B-like setup\\nuv run memory_estimator_kv_sharing.py \\\\\\n  --context_length 131072 \\\\\\n  --emb_dim 2048 \\\\\\n  --n_heads 8 \\\\\\n  --n_layers 35 \\\\\\n  --n_kv_groups 8 \\\\\\n  --n_kv_producing_layers 15 \\\\\\n  --batch_size 1 \\\\\\n  --dtype bf16\\n\\n# Gemma 4 E4B-like setup\\n# uv run memory_estimator_kv_sharing.py \\\\\\n#   --context_length 131072 \\\\\\n#   --emb_dim 2560 \\\\\\n#   --n_heads 8 \\\\\\n#   --n_layers 42 \\\\\\n#   --n_kv_groups 4 \\\\\\n#   --n_kv_producing_layers 24 \\\\\\n#   --batch_size 1 \\\\\\n#   --dtype bf16\\n\\n==== Config ====\\ncontext_length         : 131072\\nemb_dim                : 2048\\nn_heads                : 8\\nn_layers               : 35\\nn_kv_groups            : 8\\nn_kv_producing_layers  : 15\\nbatch_size             : 1\\ndtype                  : bf16 (2 Bytes/elem)\\nhead_dim               : 256\\nGQA n_kv_heads         : 1\\n\\n==== KV-cache totals across all layers ====\\nMHA total KV cache        : 37.58 GB\\nGQA total KV cache        : 4.70 GB\\nMHA + KV sharing          : 16.11 GB\\nGQA + KV sharing          : 2.01 GB\\nRatio (MHA / GQA+sharing) : 18.67x\\nSavings vs MHA            : 94.64%\\n```\\n\\nThis is a Gemma 4 E2B-like setup. The 35 layers include 15 K/V-producing layers, and the remaining layers reuse earlier K/V tensors. For the E4B-like setup, the corresponding numbers are 42 total layers and 24 K/V-producing layers.\\n\\nThe savings are shown below for the E2B-like and E4B-like setups. For simplicity, these plots do not include additional savings from sliding window attention.\\n\\n&nbsp;\\n\\n<img src=\\\"kv_memory_mha_gqa_kvsharing_gemma4_e2b.webp\\\" alt=\\\"KV-sharing memory savings for Gemma 4 E2B-like setup\\\" width=\\\"800px\\\" />\\n\\n&nbsp;\\n\\n<img src=\\\"kv_memory_mha_gqa_kvsharing_gemma4_e4b.webp\\\" alt=\\\"KV-sharing memory savings for Gemma 4 E4B-like setup\\\" width=\\\"800px\\\" />\\n\\n&nbsp;\\n\\nYou can reproduce similar plots via:\\n\\n```bash\\nuv run plot_memory_estimates_kv_sharing.py --preset gemma4_e2b\\nuv run plot_memory_estimates_kv_sharing.py --preset gemma4_e4b\\n```\\n\\n&nbsp;\\n## KV-Sharing Code Examples\\n\\nThe [gpt_with_kv_mha.py](gpt_with_kv_mha.py) and [gpt_with_kv_sharing.py](gpt_with_kv_sharing.py) scripts in this folder provide hands-on examples for comparing regular MHA with a cross-layer KV-sharing variant.\\n\\nThe easiest way to see the implementation details is to inspect a file diff between [gpt_with_kv_mha.py](gpt_with_kv_mha.py) and [gpt_with_kv_sharing.py](gpt_with_kv_sharing.py). The comments are intentionally kept similar so that the diff highlights the KV-sharing changes.\\n\\nNote that the model is not trained and thus generates nonsensical text. However, you can use it as a drop-in replacement for the standard GPT model in chapters 5-7 and train it.\\n\\nAlso, this implementation uses the KV cache explained in [another bonus section](../03_kv-cache), so the memory savings are more pronounced.\\n\\n```bash\\nuv run gpt_with_kv_mha.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 768\\n```\\n\\n```bash\\nuv run gpt_with_kv_sharing.py \\\\\\n--max_new_tokens 32768 \\\\\\n--n_heads 24 \\\\\\n--n_layers 12 \\\\\\n--emb_dim 768 \\\\\\n--n_kv_producing_layers 6\\n```\\n\\nIn this small GPT setup, the whole model still contains the same feed-forward layers and output head. The main memory difference is in how many attention layers store K/V tensors in the cache.\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/10_kv-sharing/gpt_with_kv_mha.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"67cdfab5f7873d0436de0ff37029fd2e081020a4f0ef1cb72a2342a902a6cab2\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttention(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False):\\n        b, num_tokens, d_in = x.shape\\n\\n        keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n        values_new = self.W_value(x)\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if use_cache:\\n            if self.cache_k is None:\\n                self.cache_k, self.cache_v = keys_new, values_new\\n            else:\\n                self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n            keys, values = self.cache_k, self.cache_v\\n        else:\\n            keys, values = keys_new, values_new\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttention(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x = self.att(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        for blk in self.trf_blocks:\\n            x = blk(x, use_cache=use_cache)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(\\n        formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"Run GPT with standard multi-head attention.\\\"\\n    )\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/10_kv-sharing/gpt_with_kv_sharing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"96e8d83253a26198112389250dcc8e1218159b8e409767472aaab691e85841bd\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# This file collects all the relevant code that we covered thus far\\n# throughout Chapters 3-4, adapted to use cross-layer KV sharing.\\n# This file can be run as a standalone script.\\n\\nimport argparse\\nimport time\\nimport tiktoken\\nimport torch\\nimport torch.nn as nn\\n\\n\\n#####################################\\n# Chapter 3\\n#####################################\\nclass MultiHeadAttentionWithKVSharing(nn.Module):\\n    def __init__(self, d_in, d_out, dropout, num_heads, qkv_bias=False):\\n        super().__init__()\\n        assert d_out % num_heads == 0, \\\"d_out must be divisible by num_heads\\\"\\n\\n        self.d_out = d_out\\n        self.num_heads = num_heads\\n        self.head_dim = d_out // num_heads  # Reduce the projection dim to match desired output dim\\n\\n        self.W_query = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_key = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.W_value = nn.Linear(d_in, d_out, bias=qkv_bias)\\n        self.out_proj = nn.Linear(d_out, d_out)  # Linear layer to combine head outputs\\n        self.dropout = nn.Dropout(dropout)\\n\\n        ####################################################\\n        # KV cache-related code\\n        self.register_buffer(\\\"cache_k\\\", None, persistent=False)\\n        self.register_buffer(\\\"cache_v\\\", None, persistent=False)\\n        self.ptr_current_pos = 0\\n        ####################################################\\n\\n    def forward(self, x, use_cache=False, shared_kv=None):\\n        b, num_tokens, d_in = x.shape\\n\\n        queries = self.W_query(x)\\n\\n        # We implicitly split the matrix by adding a `num_heads` dimension\\n        # Unroll last dim: (b, num_tokens, d_out) -> (b, num_tokens, num_heads, head_dim)\\n        queries = queries.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n        ####################################################\\n        # KV cache-related\\n        if shared_kv is None:\\n            keys_new = self.W_key(x)  # Shape: (b, num_tokens, d_out)\\n            values_new = self.W_value(x)\\n\\n            keys_new = keys_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n            values_new = values_new.view(b, num_tokens, self.num_heads, self.head_dim)\\n\\n            if use_cache:\\n                if self.cache_k is None:\\n                    self.cache_k, self.cache_v = keys_new, values_new\\n                else:\\n                    self.cache_k = torch.cat([self.cache_k, keys_new], dim=1)\\n                    self.cache_v = torch.cat([self.cache_v, values_new], dim=1)\\n                keys, values = self.cache_k, self.cache_v\\n            else:\\n                keys, values = keys_new, values_new\\n                if self.cache_k is not None or self.cache_v is not None:\\n                    self.reset_cache()\\n\\n            new_shared_kv = (keys, values)\\n        else:\\n            keys, values = shared_kv\\n            new_shared_kv = None\\n        ####################################################\\n\\n        # Transpose: (b, num_tokens, num_heads, head_dim) -> (b, num_heads, num_tokens, head_dim)\\n        keys = keys.transpose(1, 2)\\n        queries = queries.transpose(1, 2)\\n        values = values.transpose(1, 2)\\n\\n        # Compute scaled dot-product attention (aka self-attention) with a causal mask\\n        attn_scores = queries @ keys.transpose(2, 3)  # Dot product for each head\\n\\n        ####################################################\\n        # causal mask\\n        num_tokens_Q = queries.shape[-2]\\n        num_tokens_K = keys.shape[-2]\\n        device = queries.device\\n        if use_cache:\\n            q_positions = torch.arange(\\n                self.ptr_current_pos,\\n                self.ptr_current_pos + num_tokens_Q,\\n                device=device,\\n                dtype=torch.long,\\n            )\\n            self.ptr_current_pos += num_tokens_Q\\n        else:\\n            q_positions = torch.arange(num_tokens_Q, device=device, dtype=torch.long)\\n            self.ptr_current_pos = 0\\n        k_positions = torch.arange(num_tokens_K, device=device, dtype=torch.long)\\n        mask_bool = q_positions.unsqueeze(-1) < k_positions.unsqueeze(0)\\n\\n        # Use the mask to fill attention scores\\n        attn_scores.masked_fill_(mask_bool, -torch.inf)\\n\\n        attn_weights = torch.softmax(attn_scores / keys.shape[-1]**0.5, dim=-1)\\n        attn_weights = self.dropout(attn_weights)\\n\\n        # Shape: (b, num_tokens, num_heads, head_dim)\\n        context_vec = (attn_weights @ values).transpose(1, 2)\\n\\n        # Combine heads, where self.d_out = self.num_heads * self.head_dim\\n        context_vec = context_vec.contiguous().view(b, num_tokens, self.d_out)\\n        context_vec = self.out_proj(context_vec)  # optional projection\\n\\n        return context_vec, new_shared_kv\\n\\n    def reset_cache(self):\\n        self.cache_k, self.cache_v = None, None\\n        self.ptr_current_pos = 0\\n\\n\\n#####################################\\n# Chapter 4\\n#####################################\\nclass LayerNorm(nn.Module):\\n    def __init__(self, emb_dim):\\n        super().__init__()\\n        self.eps = 1e-5\\n        self.scale = nn.Parameter(torch.ones(emb_dim))\\n        self.shift = nn.Parameter(torch.zeros(emb_dim))\\n\\n    def forward(self, x):\\n        mean = x.mean(dim=-1, keepdim=True)\\n        var = x.var(dim=-1, keepdim=True, unbiased=False)\\n        norm_x = (x - mean) / torch.sqrt(var + self.eps)\\n        return self.scale * norm_x + self.shift\\n\\n\\nclass GELU(nn.Module):\\n    def __init__(self):\\n        super().__init__()\\n\\n    def forward(self, x):\\n        return 0.5 * x * (1 + torch.tanh(\\n            torch.sqrt(torch.tensor(2.0 / torch.pi)) *\\n            (x + 0.044715 * torch.pow(x, 3))\\n        ))\\n\\n\\nclass FeedForward(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.layers = nn.Sequential(\\n            nn.Linear(cfg[\\\"emb_dim\\\"], 4 * cfg[\\\"emb_dim\\\"]),\\n            GELU(),\\n            nn.Linear(4 * cfg[\\\"emb_dim\\\"], cfg[\\\"emb_dim\\\"]),\\n        )\\n\\n    def forward(self, x):\\n        return self.layers(x)\\n\\n\\nclass TransformerBlock(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        self.att = MultiHeadAttentionWithKVSharing(\\n            d_in=cfg[\\\"emb_dim\\\"],\\n            d_out=cfg[\\\"emb_dim\\\"],\\n            num_heads=cfg[\\\"n_heads\\\"],\\n            dropout=cfg[\\\"drop_rate\\\"],\\n            qkv_bias=cfg[\\\"qkv_bias\\\"])\\n        self.ff = FeedForward(cfg)\\n        self.norm1 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.norm2 = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.drop_shortcut = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n    def forward(self, x, use_cache=False, shared_kv=None):\\n        # Shortcut connection for attention block\\n        shortcut = x\\n        x = self.norm1(x)\\n\\n        # x = self.att(x)   # Shape [batch_size, num_tokens, emb_size]\\n        ####################################################\\n        #  KV cache-related\\n        x, new_shared_kv = self.att(x, use_cache=use_cache, shared_kv=shared_kv)\\n        ####################################################\\n\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        # Shortcut connection for feed-forward block\\n        shortcut = x\\n        x = self.norm2(x)\\n        x = self.ff(x)\\n        x = self.drop_shortcut(x)\\n        x = x + shortcut  # Add the original input back\\n\\n        return x, new_shared_kv\\n\\n\\nclass GPTModel(nn.Module):\\n    def __init__(self, cfg):\\n        super().__init__()\\n        if not 1 <= cfg[\\\"n_kv_producing_layers\\\"] <= cfg[\\\"n_layers\\\"]:\\n            raise ValueError(\\\"n_kv_producing_layers must be between 1 and n_layers.\\\")\\n\\n        self.tok_emb = nn.Embedding(cfg[\\\"vocab_size\\\"], cfg[\\\"emb_dim\\\"])\\n        self.pos_emb = nn.Embedding(cfg[\\\"context_length\\\"], cfg[\\\"emb_dim\\\"])\\n        self.drop_emb = nn.Dropout(cfg[\\\"drop_rate\\\"])\\n\\n        # self.trf_blocks = nn.Sequential(\\n        #    *[TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        ####################################################\\n        #  KV cache-related\\n        self.trf_blocks = nn.ModuleList(\\n            [TransformerBlock(cfg) for _ in range(cfg[\\\"n_layers\\\"])])\\n        self.n_kv_producing_layers = cfg[\\\"n_kv_producing_layers\\\"]\\n        self.current_pos = 0\\n        ####################################################\\n\\n        self.final_norm = LayerNorm(cfg[\\\"emb_dim\\\"])\\n        self.out_head = nn.Linear(cfg[\\\"emb_dim\\\"], cfg[\\\"vocab_size\\\"], bias=False)\\n\\n    def forward(self, in_idx, use_cache=False):\\n        batch_size, seq_len = in_idx.shape\\n        tok_embeds = self.tok_emb(in_idx)\\n\\n        # pos_embeds = self.pos_emb(torch.arange(seq_len, device=in_idx.device))\\n\\n        ####################################################\\n        #  KV cache-related\\n        if use_cache:\\n            pos_ids = torch.arange(self.current_pos, self.current_pos + seq_len, device=in_idx.device, dtype=torch.long)\\n            self.current_pos += seq_len\\n        else:\\n            pos_ids = torch.arange(0, seq_len, device=in_idx.device, dtype=torch.long)\\n        pos_embeds = self.pos_emb(pos_ids).unsqueeze(0)\\n        ####################################################\\n\\n        x = tok_embeds + pos_embeds  # Shape [batch_size, num_tokens, emb_size]\\n        x = self.drop_emb(x)\\n\\n        # x = self.trf_blocks(x)\\n        ####################################################\\n        # KV cache-related\\n        shared_kv = None\\n        for layer_idx, blk in enumerate(self.trf_blocks):\\n            if layer_idx < self.n_kv_producing_layers:\\n                x, shared_kv = blk(x, use_cache=use_cache, shared_kv=None)\\n            else:\\n                x, _ = blk(x, use_cache=use_cache, shared_kv=shared_kv)\\n        ####################################################\\n\\n        x = self.final_norm(x)\\n        logits = self.out_head(x)\\n        return logits\\n\\n    ####################################################\\n    # KV cache-related\\n    def reset_kv_cache(self):\\n        for blk in self.trf_blocks:\\n            blk.att.reset_cache()\\n        self.current_pos = 0\\n    ####################################################\\n\\n\\ndef generate_text_simple_cached(model, idx, max_new_tokens,\\n                                context_size=None, use_cache=True):\\n    model.eval()\\n    ctx_len = context_size or model.pos_emb.num_embeddings\\n\\n    with torch.no_grad():\\n        if use_cache:\\n            # Init cache with full prompt\\n            model.reset_kv_cache()\\n            logits = model(idx[:, -ctx_len:], use_cache=True)\\n\\n            for _ in range(max_new_tokens):\\n                # a) pick the token with the highest log-probability (greedy sampling)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                # b) append it to the running sequence\\n                idx = torch.cat([idx, next_idx], dim=1)\\n                # c) feed model only the new token\\n                logits = model(next_idx, use_cache=True)\\n        else:\\n            for _ in range(max_new_tokens):\\n                logits = model(idx[:, -ctx_len:], use_cache=False)\\n                next_idx = logits[:, -1].argmax(dim=-1, keepdim=True)\\n                idx = torch.cat([idx, next_idx], dim=1)\\n\\n    return idx\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser(\\n        formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"Run GPT with cross-layer KV sharing.\\\",\\n    )\\n    parser.add_argument(\\\"--emb_dim\\\", type=int, default=768, help=\\\"Model embedding dimension.\\\")\\n    parser.add_argument(\\\"--n_heads\\\", type=int, default=12, help=\\\"Number of attention heads.\\\")\\n    parser.add_argument(\\\"--n_layers\\\", type=int, default=12, help=\\\"Number of transformer blocks.\\\")\\n    parser.add_argument(\\\"--n_kv_producing_layers\\\", type=int, default=6,\\n                        help=\\\"Number of early layers that compute and cache their own K/V tensors.\\\")\\n    parser.add_argument(\\\"--max_new_tokens\\\", type=int, default=200, help=\\\"Number of tokens to generate.\\\")\\n    args = parser.parse_args()\\n\\n    start_context = \\\"Hello, I am\\\"\\n    tokenizer = tiktoken.get_encoding(\\\"gpt2\\\")\\n    encoded = tokenizer.encode(start_context)\\n\\n    GPT_CONFIG_124M = {\\n        \\\"vocab_size\\\": 50257,        # Vocabulary size\\n        \\\"context_length\\\": args.max_new_tokens + len(encoded),\\n        \\\"emb_dim\\\": args.emb_dim,    # Embedding dimension\\n        \\\"n_heads\\\": args.n_heads,    # Number of attention heads\\n        \\\"n_layers\\\": args.n_layers,  # Number of layers\\n        \\\"drop_rate\\\": 0.0,           # Dropout rate\\n        \\\"qkv_bias\\\": False,          # Query-Key-Value bias\\n        \\\"n_kv_producing_layers\\\": args.n_kv_producing_layers,\\n    }\\n    torch.manual_seed(123)\\n    model = GPTModel(GPT_CONFIG_124M)\\n    device = torch.device(\\\"cuda\\\" if torch.cuda.is_available() else \\\"cpu\\\")\\n    model.to(device, dtype=torch.bfloat16)\\n    model.eval()  # disable dropout\\n\\n    encoded_tensor = torch.tensor(encoded, device=device).unsqueeze(0)\\n    print(f\\\"\\\\n{50*'='}\\\\n{22*' '}IN\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nInput text:\\\", start_context)\\n    print(\\\"Encoded input text:\\\", encoded)\\n    print(\\\"encoded_tensor.shape:\\\", encoded_tensor.shape)\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    start = time.time()\\n\\n    token_ids = generate_text_simple_cached(\\n        model=model,\\n        idx=encoded_tensor,\\n        max_new_tokens=args.max_new_tokens,\\n    )\\n\\n    if torch.cuda.is_available():\\n        torch.cuda.synchronize()\\n    total_time = time.time() - start\\n\\n    decoded_text = tokenizer.decode(token_ids.squeeze(0).tolist())\\n\\n    print(f\\\"\\\\n\\\\n{50*'='}\\\\n{22*' '}OUT\\\\n{50*'='}\\\")\\n    print(\\\"\\\\nOutput:\\\", token_ids)\\n    print(\\\"Output length:\\\", len(token_ids[0]))\\n    print(\\\"Output text:\\\", decoded_text)\\n\\n    print(f\\\"\\\\nTime: {total_time:.2f} sec\\\")\\n    print(f\\\"{int(len(token_ids[0])/total_time)} tokens/sec\\\")\\n    if torch.cuda.is_available():\\n        max_mem_bytes = torch.cuda.max_memory_allocated()\\n        max_mem_gb = max_mem_bytes / (1024 ** 3)\\n        print(f\\\"Max memory allocated: {max_mem_gb:.2f} GB\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/10_kv-sharing/memory_estimator_kv_sharing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"619005d058a9afc04abc6550ccef37fc920468354bfe3071d08f414362fbbb7d\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n# KV-cache memory estimator for MHA, GQA, and cross-layer KV sharing.\\n\\nimport argparse\\nimport math\\n\\nDTYPE_BYTES = {\\n    \\\"fp32\\\": 4,\\n    \\\"bf16\\\": 2,\\n    \\\"fp16\\\": 2,\\n    \\\"fp8\\\": 1,\\n    \\\"int8\\\": 1,\\n}\\n\\n\\ndef convert_bytes(n):\\n    gb = n / (1000 ** 3)\\n    return f\\\"{gb:,.2f} GB\\\"\\n\\n\\ndef calc_kv_bytes_total(batch, context_length, emb_dim, n_heads,\\n                        n_kv_heads, n_cached_layers, bytes_per_elem):\\n    head_dim = math.ceil(emb_dim / n_heads)\\n    per_layer = batch * context_length * head_dim * n_kv_heads * 2 * bytes_per_elem\\n    return per_layer * n_cached_layers\\n\\n\\ndef main():\\n    p = argparse.ArgumentParser(\\n        formatter_class=argparse.ArgumentDefaultsHelpFormatter,\\n        description=\\\"Estimate KV-cache memory for MHA, GQA, and cross-layer KV sharing\\\",\\n    )\\n    p.add_argument(\\\"--context_length\\\", default=1024, type=int)\\n    p.add_argument(\\\"--emb_dim\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_heads\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_layers\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_kv_groups\\\", required=True, type=int)\\n    p.add_argument(\\\"--n_kv_producing_layers\\\", required=True, type=int)\\n    p.add_argument(\\\"--batch_size\\\", default=1, type=int)\\n    p.add_argument(\\\"--dtype\\\", choices=DTYPE_BYTES.keys(), default=\\\"fp16\\\")\\n    args = p.parse_args()\\n\\n    cfg = {\\n        \\\"context_length\\\": args.context_length,\\n        \\\"emb_dim\\\": args.emb_dim,\\n        \\\"n_heads\\\": args.n_heads,\\n        \\\"n_layers\\\": args.n_layers,\\n        \\\"n_kv_groups\\\": args.n_kv_groups,\\n        \\\"n_kv_producing_layers\\\": args.n_kv_producing_layers,\\n    }\\n\\n    if cfg[\\\"n_heads\\\"] % cfg[\\\"n_kv_groups\\\"] != 0:\\n        raise ValueError(\\\"n_kv_groups must divide n_heads exactly.\\\")\\n    if not 1 <= cfg[\\\"n_kv_producing_layers\\\"] <= cfg[\\\"n_layers\\\"]:\\n        raise ValueError(\\\"n_kv_producing_layers must be between 1 and n_layers.\\\")\\n\\n    bytes_per_elem = DTYPE_BYTES[args.dtype]\\n    head_dim = math.ceil(cfg[\\\"emb_dim\\\"] / cfg[\\\"n_heads\\\"])\\n\\n    n_kv_heads_mha = cfg[\\\"n_heads\\\"]\\n    n_kv_heads_gqa = cfg[\\\"n_heads\\\"] // cfg[\\\"n_kv_groups\\\"]\\n\\n    total_mha = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_mha,\\n        cfg[\\\"n_layers\\\"],\\n        bytes_per_elem,\\n    )\\n    total_gqa = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_gqa,\\n        cfg[\\\"n_layers\\\"],\\n        bytes_per_elem,\\n    )\\n    total_mha_sharing = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_mha,\\n        cfg[\\\"n_kv_producing_layers\\\"],\\n        bytes_per_elem,\\n    )\\n    total_gqa_sharing = calc_kv_bytes_total(\\n        args.batch_size,\\n        cfg[\\\"context_length\\\"],\\n        cfg[\\\"emb_dim\\\"],\\n        cfg[\\\"n_heads\\\"],\\n        n_kv_heads_gqa,\\n        cfg[\\\"n_kv_producing_layers\\\"],\\n        bytes_per_elem,\\n    )\\n\\n    print(\\\"==== Config ====\\\")\\n    for k, v in cfg.items():\\n        print(f\\\"{k:23}: {v}\\\")\\n    print(f\\\"batch_size             : {args.batch_size}\\\")\\n    print(f\\\"dtype                  : {args.dtype} ({bytes_per_elem} Bytes/elem)\\\")\\n    print(f\\\"head_dim               : {head_dim}\\\")\\n    print(f\\\"GQA n_kv_heads         : {n_kv_heads_gqa}\\\")\\n    print()\\n\\n    print(\\\"==== KV-cache totals across all layers ====\\\")\\n    print(f\\\"MHA total KV cache        : {convert_bytes(total_mha)}\\\")\\n    print(f\\\"GQA total KV cache        : {convert_bytes(total_gqa)}\\\")\\n    print(f\\\"MHA + KV sharing          : {convert_bytes(total_mha_sharing)}\\\")\\n    print(f\\\"GQA + KV sharing          : {convert_bytes(total_gqa_sharing)}\\\")\\n    print(f\\\"Ratio (MHA / GQA+sharing) : {total_mha / total_gqa_sharing:,.2f}x\\\")\\n    print(f\\\"Savings vs MHA            : {(1 - total_gqa_sharing / total_mha) * 100:,.2f}%\\\")\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LLMs-from-scratch\",\"source_path\":\"ch04/10_kv-sharing/plot_memory_estimates_kv_sharing.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"095aea7d3a3664b38894f7a175dddf43b8385683903e061b727ae6ca7b55c9aa\",\"content\":\"# Copyright (c) Sebastian Raschka under Apache License 2.0 (see LICENSE.txt).\\n# Source for \\\"Build a Large Language Model From Scratch\\\"\\n#   - https://www.manning.com/books/build-a-large-language-model-from-scratch\\n# Code: https://github.com/rasbt/LLMs-from-scratch\\n\\n\\\"\\\"\\\"Plot KV-cache memory for MHA, GQA, and cross-layer KV sharing.\\\"\\\"\\\"\\n\\nimport argparse\\nfrom pathlib import Path\\n\\nimport matplotlib.pyplot as plt\\nfrom matplotlib.ticker import FixedLocator, FuncFormatter\\n\\n\\nDTYPE_BYTES = {\\";
